void
mapc2p(double t, const double *xn, double *GKYL_RESTRICT fout, void *ctx)
{
  double r = xn[0], theta = xn[1], z = xn[2];
  fout[0] = r * cos(theta);
  fout[1] = r * sin(theta);
  fout[2] = z;
}

void
exact_gij(double t, const double *xn, double *GKYL_RESTRICT fout, void *ctx)
{
  double r = xn[0], theta = xn[1], phi = xn[2];
  fout[0] = 1.0;
  fout[1] = 0.0;
  fout[2] = 0.0;
  fout[3] = r * r;
  fout[4] = 0.0;
  fout[5] = 1.0;
}

