    up->tri[i] = gkyl_mat_triples_new(up->numnodes_global, up->numnodes_global);
#ifdef GKYL_HAVE_CUDA
    if (up->use_gpu) {
      gkyl_mat_triples_set_rowmaj_order(up->tri[i]);
    }
#endif
  }

  // Assign non-zero elements in A.
  int idx0[GKYL_MAX_CDIM], idx1[GKYL_MAX_CDIM];
  gkyl_range_iter_init(&up->par_iter1d, &up->par_range1d);
  while (gkyl_range_iter_next(&up->par_iter1d)) {
    long paridx = gkyl_range_idx(&up->par_range1d, up->par_iter1d.idx);

    gkyl_range_iter_init(&up->perp_iter2d, &up->perp_range2d);
    while (gkyl_range_iter_next(&up->perp_iter2d)) {
      long perpidx = gkyl_range_idx(&up->perp_range2d, up->perp_iter2d.idx);

      for (size_t d = 0; d < up->ndim_perp; d++) {
        idx1[d] = up->perp_iter2d.idx[d];
      }
      idx1[up->pardir] = up->par_iter1d.idx[0];

      long linidx = gkyl_range_idx(up->solve_range, idx1);

      double *eps_p = gkyl_array_fetch(epsilon_ho, linidx);
      double *kSq_p = up->ishelmholtz ? gkyl_array_fetch(kSq_ho, linidx) :
                                        gkyl_array_fetch(kSq_ho, 0);

      int keri = idx_to_inup_ker(up->ndim_perp, up->num_cells, up->perp_iter2d.idx);
      for (size_t d = 0; d < up->ndim; d++) {
        idx0[d] = idx1[d] - 1;
      }
      up->kernels->l2g[keri](up->num_cells, idx0, up->globalidx);

      // Apply the -nabla . (epsilon*nabla_perp)-kSq stencil.
      keri = idx_to_inloup_ker(up->ndim_perp, up->num_cells, idx1);
      up->kernels->lhsker[keri](eps_p, kSq_p, up->dx, up->bcvals, up->globalidx, up->tri[paridx]);
    }
  }

  if (up->num_bias_line > 0) {
    // If biased lines are specified, replace the corresponding equation in the
    // linear system so it only has a 1.
    gkyl_range_iter_init(&up->par_iter1d, &up->par_range1d);
    while (gkyl_range_iter_next(&up->par_iter1d)) {
      long paridx = gkyl_range_idx(&up->par_range1d, up->par_iter1d.idx);

      gkyl_range_iter_init(&up->perp_iter2d, &up->perp_range2d);
      while (gkyl_range_iter_next(&up->perp_iter2d)) {
        long perpidx = gkyl_range_idx(&up->perp_range2d, up->perp_iter2d.idx);

        for (size_t d = 0; d < up->ndim_perp; d++) {
          idx1[d] = up->perp_iter2d.idx[d];
        }
        idx1[up->pardir] = up->par_iter1d.idx[0];

        int keri = idx_to_inup_ker(up->ndim_perp, up->num_cells, up->perp_iter2d.idx);
        for (size_t d = 0; d < up->ndim; d++) {
          idx0[d] = idx1[d] - 1;
        }
        up->kernels->l2g[keri](up->num_cells, idx0, up->globalidx);

        for (int i = 0; i < bias_lines->num_bias_line; i++) {
          if (bl_in_solve_range[i]) {
            // Index of the cell that abuts the line from below.
            struct gkyl_poisson_bias_line *bl = &bias_lines->bl[i];
            int bl_idx_m[up->bl_ndim_perp];
            for (int d = 0; d < up->bl_ndim_perp; d++) {
              int perp_dir = bl->perp_dirs[d];
              double dx = up->grid.dx[perp_dir];
              bl_idx_m[d] = (bl->perp_coords[d] - 1e-3 * dx - up->grid.lower[perp_dir]) / dx + 1;
            }

            if ((idx1[bl->perp_dirs[0]] == bl_idx_m[0] && idx1[bl->perp_dirs[1]] == bl_idx_m[1]) ||
                (idx1[bl->perp_dirs[0]] == bl_idx_m[0] + 1 && idx1[bl->perp_dirs[1]] == bl_idx_m[1]
                ) ||
                (idx1[bl->perp_dirs[0]] == bl_idx_m[0] && idx1[bl->perp_dirs[1]] == bl_idx_m[1] + 1
                ) ||
                (idx1[bl->perp_dirs[0]] == bl_idx_m[0] + 1 &&
                 idx1[bl->perp_dirs[1]] == bl_idx_m[1] + 1)) {
              int edge[2] = {
                -1 + 2 * ((bl_idx_m[0] + 1) - idx1[bl->perp_dirs[0]]),
                -1 + 2 * ((bl_idx_m[1] + 1) - idx1[bl->perp_dirs[1]])
              };
              up->kernels->bias_lhs_ker[keri](edge, bl->perp_dirs, up->globalidx, up->tri[paridx]);
            }
          }
        }
      }
    }

    up->bias_line_src = fem_poisson_perp_bias_src_enabled;
  } else {
    up->bias_line_src = fem_poisson_perp_bias_src_disabled;
  }

  if (bl_in_solve_range) {
    gkyl_free(bl_in_solve_range);
  }

#ifdef GKYL_HAVE_CUDA
  if (up->use_gpu) {
    assert(gkyl_array_is_cu_dev(rhsin));

    gkyl_fem_poisson_perp_set_rhs_cu(up, rhsin);
    return;
  }
#endif

  gkyl_array_clear(up->brhs, 0.0);
  double *brhs_p = gkyl_array_fetch(up->brhs, 0);

  int idx0[GKYL_MAX_CDIM], idx1[GKYL_MAX_CDIM];
  gkyl_range_iter_init(&up->par_iter1d, &up->par_range1d);
  while (gkyl_range_iter_next(&up->par_iter1d)) {
    long paridx = gkyl_range_idx(&up->par_range1d, up->par_iter1d.idx);

    gkyl_range_iter_init(&up->perp_iter2d, &up->perp_range2d);
    while (gkyl_range_iter_next(&up->perp_iter2d)) {
      long perpidx = gkyl_range_idx(&up->perp_range2d, up->perp_iter2d.idx);

      for (size_t d = 0; d < up->ndim_perp; d++) {
        idx1[d] = up->perp_iter2d.idx[d];
      }
      idx1[up->pardir] = up->par_iter1d.idx[0];

      long linidx = gkyl_range_idx(up->solve_range, idx1);

      double *eps_p = gkyl_array_fetch(up->epsilon, linidx);
      double *rhsin_p = gkyl_array_fetch(rhsin, linidx);

      int keri = idx_to_inup_ker(up->ndim_perp, up->num_cells, up->perp_iter2d.idx);
      for (size_t d = 0; d < up->ndim; d++) {
        idx0[d] = idx1[d] - 1;
      }
      up->kernels->l2g[keri](up->num_cells, idx0, up->globalidx);

      // Apply the RHS source stencil. It's mostly the mass matrix times a
      // modal-to-nodal operator times the source, modified by BCs in skin cells.
      keri = idx_to_inloup_ker(up->ndim_perp, up->num_cells, idx1);

      long parProbOff = paridx * up->numnodes_global;

      up->kernels->srcker[keri](
        eps_p, up->dx, rhsin_p, up->bcvals, parProbOff, up->globalidx, brhs_p
      );
    }
  }

  // Set the corresponding entries to the biasing potential.
  up->bias_line_src(up, rhsin);

  gkyl_superlu_brhs_from_array(up->prob, brhs_p);
}

void
gkyl_fem_poisson_perp_solve(gkyl_fem_poisson_perp *up, struct gkyl_array *phiout)
{
#ifdef GKYL_HAVE_CUDA
  if (up->use_gpu) {
    assert(gkyl_array_is_cu_dev(phiout));
    gkyl_fem_poisson_perp_solve_cu(up, phiout);
    return;
  }
#endif

  gkyl_superlu_solve(up->prob);

  gkyl_array_clear(phiout, 0.0);

  int idx0[GKYL_MAX_CDIM], idx1[GKYL_MAX_CDIM];
  gkyl_range_iter_init(&up->par_iter1d, &up->par_range1d);
  while (gkyl_range_iter_next(&up->par_iter1d)) {
    long paridx = gkyl_range_idx(&up->par_range1d, up->par_iter1d.idx);

    gkyl_range_iter_init(&up->perp_iter2d, &up->perp_range2d);
    while (gkyl_range_iter_next(&up->perp_iter2d)) {
      long perpidx = gkyl_range_idx(&up->perp_range2d, up->perp_iter2d.idx);

      for (size_t d = 0; d < up->ndim_perp; d++) {
        idx1[d] = up->perp_iter2d.idx[d];
      }
      idx1[up->pardir] = up->par_iter1d.idx[0];

      long linidx = gkyl_range_idx(up->solve_range, idx1);

      double *phiout_p = gkyl_array_fetch(phiout, linidx);

      int keri = idx_to_inup_ker(up->ndim_perp, up->num_cells, up->perp_iter2d.idx);
      for (size_t d = 0; d < up->ndim; d++) {
        idx0[d] = idx1[d] - 1;
      }
      up->kernels->l2g[keri](up->num_cells, idx0, up->globalidx);

      long parProbOff = paridx * up->numnodes_global;

      up->kernels->solker(
        gkyl_superlu_get_rhs_ptr(up->prob, 0), parProbOff, up->globalidx, phiout_p
      );
    }
  }
}

void
gkyl_fem_poisson_perp_update_lhs(
  gkyl_fem_poisson_perp *up, struct gkyl_array *epsilon, struct gkyl_array *kSq
)
{
  assert(up->num_bias_line == 0); // Have not accounted for bias in csr_val_idx.
#ifdef GKYL_HAVE_CUDA
  if (up->use_gpu) {
    assert(gkyl_array_is_cu_dev(epsilon));
    if (up->ishelmholtz) {
      assert(gkyl_array_is_cu_dev(kSq));
    }

    gkyl_fem_poisson_perp_update_lhs_cu(up, epsilon, kSq);
    return;
  }
#endif

  int idx0[GKYL_MAX_CDIM], idx1[GKYL_MAX_CDIM];
  gkyl_range_iter_init(&up->par_iter1d, &up->par_range1d);
  while (gkyl_range_iter_next(&up->par_iter1d)) {
    long paridx = gkyl_range_idx(&up->par_range1d, up->par_iter1d.idx);

    // Clear mat triples.
    gkyl_mat_triples_clear(up->tri[paridx], 0.0);

    gkyl_range_iter_init(&up->perp_iter2d, &up->perp_range2d);
    while (gkyl_range_iter_next(&up->perp_iter2d)) {
      long perpidx = gkyl_range_idx(&up->perp_range2d, up->perp_iter2d.idx);

      for (size_t d = 0; d < up->ndim_perp; d++) {
        idx1[d] = up->perp_iter2d.idx[d];
      }
      idx1[up->pardir] = up->par_iter1d.idx[0];

      long linidx = gkyl_range_idx(up->solve_range, idx1);

      double *eps_p = gkyl_array_fetch(epsilon, linidx);
      double *kSq_p = up->ishelmholtz ? gkyl_array_fetch(kSq, linidx) :
                                        gkyl_array_fetch(up->kSq_null, 0);

      int keri = idx_to_inup_ker(up->ndim_perp, up->num_cells, up->perp_iter2d.idx);
      for (size_t d = 0; d < up->ndim; d++) {
        idx0[d] = idx1[d] - 1;
      }
      up->kernels->l2g[keri](up->num_cells, idx0, up->globalidx);

      // Apply the -nabla . (epsilon*nabla_perp)-kSq stencil.
      keri = idx_to_inloup_ker(up->ndim_perp, up->num_cells, idx1);
      up->kernels->lhsker[keri](eps_p, kSq_p, up->dx, up->bcvals, up->globalidx, up->tri[paridx]);
    }
  }

  gkyl_superlu_amat_update_from_triples(up->prob, up->tri);
}

void
gkyl_fem_poisson_perp_release(struct gkyl_fem_poisson_perp *up)
{
  if (up->isdomperiodic) {
    gkyl_array_release(up->rhs_cellavg);
    gkyl_free(up->rhs_avg);
  }

  if (!(up->ishelmholtz)) {
    gkyl_array_release(up->kSq_null);
  }

  if (!(up->use_gpu)) {
    for (size_t i = 0; i < up->par_range.volume; i++) {
      gkyl_mat_triples_release(up->tri[i]);
    }

RESULT 2
  gkyl_array_release(wall->phi);
  if (wall->projector) {
    gkyl_eval_on_nodes_release(wall->projector);
    if (app->use_gpu) {
      gkyl_array_release(wall->phi_host);
    }
  }
}

static void
gk_species_apply_bc_dynamic(
  gkyl_gyrokinetic_app *app, struct gk_species *species, double tm, struct gkyl_array *f
)
{
  struct timespec wst = gkyl_wall_clock();

  int num_periodic_dir = species->num_periodic_dir, cdim = app->cdim;
  gkyl_comm_array_per_sync(
    species->comm, &species->local, &species->local_ext, num_periodic_dir, species->periodic_dirs, f
  );

  for (int d = 0; d < cdim; ++d) {
    if (species->bc_is_np[d]) {
      switch (species->lower_bc[d].type) {
        case GKYL_BC_GK_SPECIES_SHEATH_CONDUCTING:
          gk_species_phi_wall_advance(app, &species->phi_wall_lo, tm);
          gkyl_bc_sheath_gyrokinetic_advance(
            species->bc_sheath_lo, app->field->phi_smooth, species->phi_wall_lo.phi, NULL, NULL,
            NULL, NULL, f, &app->local
          );
          break;
        case GKYL_BC_GK_SPECIES_SHEATH_SURROGATE:
          gk_species_phi_wall_advance(app, &species->phi_wall_lo, tm);
          gk_species_moment_calc(&species->sheath_moms, species->local, app->local, f);
          gk_species_moment_diag_jacobgeo_div(
            app, &species->sheath_moms, species->sheath_moms.marr, species->sheath_moms.marr
          );
          gkyl_array_set_offset_range(
            species->dens_sheath, 1.0, species->sheath_moms.marr, 0, &app->local
          );
          gkyl_array_set_offset_range(
            species->temp_sheath, species->info.mass, species->sheath_moms.marr,
            2 * app->basis.num_basis, &app->local
          );
          gkyl_bc_sheath_gyrokinetic_advance(
            species->bc_sheath_lo, app->field->phi_smooth, species->phi_wall_lo.phi,
            species->dens_sheath, species->temp_sheath, app->gk_geom->geo_int.bmag,
            app->gk_geom->geo_surf[d].bimpactangle, f, &app->local
          );
          break;
        case GKYL_BC_GK_SPECIES_TWISTSHIFT:
          gkyl_bc_twistshift_advance(species->bc_ts_lo, f, f);
          break;
        case GKYL_BC_GK_SPECIES_COPY:
        case GKYL_BC_GK_SPECIES_REFLECT:
        case GKYL_BC_GK_SPECIES_ABSORB:
          gkyl_bc_basic_gyrokinetic_advance(species->bc_lo[d], species->bc_buffer, f);
          break;
        case GKYL_BC_GK_SPECIES_FIXED_FUNC:
          gkyl_bc_basic_gyrokinetic_advance(species->bc_lo[d], species->bc_buffer_lo_fixed, f);
          break;
        case GKYL_BC_GK_SPECIES_ZERO_FLUX:
          break; // do nothing, BCs already applied in hyper_dg loop by not updating flux
        default:
          break;
      }

      switch (species->upper_bc[d].type) {
        case GKYL_BC_GK_SPECIES_SHEATH_CONDUCTING:
          gk_species_phi_wall_advance(app, &species->phi_wall_up, tm);
          gkyl_bc_sheath_gyrokinetic_advance(
            species->bc_sheath_up, app->field->phi_smooth, species->phi_wall_up.phi, NULL, NULL,
            NULL, NULL, f, &app->local
          );
          break;
        case GKYL_BC_GK_SPECIES_SHEATH_SURROGATE:
          gk_species_phi_wall_advance(app, &species->phi_wall_up, tm);
          gk_species_moment_calc(&species->sheath_moms, species->local, app->local, f);
          gk_species_moment_diag_jacobgeo_div(
            app, &species->sheath_moms, species->sheath_moms.marr, species->sheath_moms.marr
          );
          gkyl_array_set_offset_range(
            species->dens_sheath, 1.0, species->sheath_moms.marr, 0, &app->local
          );
          gkyl_array_set_offset_range(
            species->temp_sheath, species->info.mass, species->sheath_moms.marr,
            2 * app->basis.num_basis, &app->local
          );
          gkyl_bc_sheath_gyrokinetic_advance(
            species->bc_sheath_up, app->field->phi_smooth, species->phi_wall_up.phi,
            species->dens_sheath, species->temp_sheath, app->gk_geom->geo_int.bmag,
            app->gk_geom->geo_surf[d].bimpactangle, f, &app->local
          );
          break;
        case GKYL_BC_GK_SPECIES_TWISTSHIFT:
          gkyl_bc_twistshift_advance(species->bc_ts_up, f, f);
          break;
        case GKYL_BC_GK_SPECIES_COPY:
        case GKYL_BC_GK_SPECIES_REFLECT:
        case GKYL_BC_GK_SPECIES_ABSORB:
          gkyl_bc_basic_gyrokinetic_advance(species->bc_up[d], species->bc_buffer, f);
          break;
        case GKYL_BC_GK_SPECIES_FIXED_FUNC:
          gkyl_bc_basic_gyrokinetic_advance(species->bc_up[d], species->bc_buffer_up_fixed, f);
          break;
        case GKYL_BC_GK_SPECIES_ZERO_FLUX:
          break; // do nothing, BCs already applied in hyper_dg loop by not updating flux
        default:
          break;
      }
    }
  }

  if (app->gk_geom->has_LCFS && app->cdim == 3) {
    // Apply twistshift.
    gkyl_bc_twistshift_advance(species->bc_ts_lo, f, f);
    gkyl_bc_twistshift_advance(species->bc_ts_up, f, f);
  }

  gkyl_comm_array_sync(species->comm, &species->local, &species->local_ext, f);

