void
gyrokinetic_cuts_check(
  struct gkyl_gyrokinetic_app *app, struct gkyl_comm *comm, const int *cuts, FILE *iostream
)
{
  // A temporary function that checks the consistency of the communicator and
  // cuts provided for a simulation (e.g at the moment we only decompose along
  // z, and we need to check that cuts meets that requirement).
  int cdim = app->cdim;

  // Create decomposition.
  int cuts_used[cdim];
#ifdef GKYL_HAVE_MPI
  for (int d = 0; d < cdim; d++) {
    cuts_used[d] = cuts[d];
  }
#else
  for (int d = 0; d < cdim; d++) {
    cuts_used[d] = 1;
  }
#endif

  int comm_rank, comm_size;
  gkyl_comm_get_rank(comm, &comm_rank);
  gkyl_comm_get_size(comm, &comm_size);

  int ncuts = 1;
  for (int d = 0; d < cdim; d++) {
    ncuts *= cuts_used[d];
  }

  if (ncuts != comm_size) {
    if (comm_rank == 0) {
      fprintf(
        iostream, "\n*** Number of ranks, %d, does not match total cuts, %d!\n\n", comm_size, ncuts
      );
    }
    assert(false);
  }

  for (int d = 0; d < cdim - 1; d++) {
    if (cuts_used[d] > 1) {
      if (comm_rank == 0) {
        fprintf(
          iostream,
          "\n*** Parallelization only allowed in z. Number of ranks, %d, in direction %d cannot be "
          "> 1!\n\n",
          cuts_used[d], d
        );
      }
      assert(false);
    }
  }

  if (app->grid.cells[cdim - 1] % cuts_used[cdim - 1] != 0) {
    if (comm_rank == 0) {
      fprintf(
        iostream, "\n*** Number of cells in z, %d, not divisible by number of cuts, %d!\n\n",
        app->grid.cells[cdim - 1], cuts_used[cdim - 1]
      );
    }
    assert(false);
  }
}

