static void
gk_geometry_surf_calc_expansions(
  struct gk_geometry *gk_geom, int dir, struct gkyl_range nrange_quad_surf
)
{
  struct gk_geom_surf up_surf = gk_geom->geo_surf[dir];
  struct gkyl_nodal_ops *n2m = gkyl_nodal_ops_new(&gk_geom->basis, &gk_geom->grid, false);

  struct gkyl_range local_ext_in_dir;
  int lower[3] = {gk_geom->local.lower[0], gk_geom->local.lower[1], gk_geom->local.lower[2]};
  int upper[3] = {gk_geom->local.upper[0], gk_geom->local.upper[1], gk_geom->local.upper[2]};
  upper[dir] += 1;
  gkyl_sub_range_init(&local_ext_in_dir, &gk_geom->local_ext, lower, upper);

  gkyl_nodal_ops_n2m_surface(
    n2m, &gk_geom->surf_basis, &gk_geom->grid, &nrange_quad_surf, &local_ext_in_dir, 1,
    up_surf.bmag_nodal, up_surf.bmag, dir
  );
  gkyl_nodal_ops_n2m_surface(
      // Element list doesn't have this key. Create a new list with it.
      struct gkyl_msgpack_map_elem io_meta_basic_new[] = {
        {.key = "half_domain", .elem_type = GKYL_MP_UNSIGNED_INT, .uval = up->half_domain}
      };
      int io_meta_basic_new_len = sizeof(io_meta_basic_new) / sizeof(io_meta_basic_new[0]);

      struct gkyl_msgpack_map_elem *io_meta_basic_buffer =
        gkyl_msgpack_map_elem_clone(up->io_meta_basic_len, up->io_meta_basic);
      int io_meta_basic_buffer_len = up->io_meta_basic_len;
      gkyl_msgpack_map_elem_release(io_meta_basic_buffer_len, up->io_meta_basic);

      int io_meta_basic_list_len[] = {io_meta_basic_new_len, io_meta_basic_buffer_len};
      const struct gkyl_msgpack_map_elem *io_meta_basic_list[] = {
        io_meta_basic_new, io_meta_basic_buffer
      };
      up->io_meta_basic = gkyl_msgpack_map_elem_union(
        sizeof(io_meta_basic_list_len) / sizeof(int), io_meta_basic_list_len, io_meta_basic_list,
        &up->io_meta_basic_len
      );

      gkyl_msgpack_map_elem_release(io_meta_basic_buffer_len, io_meta_basic_buffer);
    }
  }
}

void
gkyl_gk_geometry_populate_nodal(struct gk_geometry *gk_geom)
{
  // Populate nodal arrays for vpar surface terms
  struct gkyl_nodal_ops *n2m = gkyl_nodal_ops_new(&gk_geom->basis, &gk_geom->grid, false);
  gkyl_nodal_ops_m2n(
    n2m, &gk_geom->basis, &gk_geom->grid, &gk_geom->nrange_int, &gk_geom->local, 1,
    gk_geom->geo_int.jacobgeo_nodal, gk_geom->geo_int.jacobgeo, true
  );
  gkyl_nodal_ops_m2n(
    n2m, &gk_geom->basis, &gk_geom->grid, &gk_geom->nrange_int, &gk_geom->local, 9,
    gk_geom->geo_int.dxdz_nodal, gk_geom->geo_int.dxdz, true
  );
  gkyl_nodal_ops_m2n(
    n2m, &gk_geom->basis, &gk_geom->grid, &gk_geom->nrange_int, &gk_geom->local, 9,
    gk_geom->geo_int.dzdx_nodal, gk_geom->geo_int.dzdx, true
  );
  gkyl_nodal_ops_m2n(
    n2m, &gk_geom->basis, &gk_geom->grid, &gk_geom->nrange_int, &gk_geom->local, 1,
    gk_geom->geo_int.bmag_nodal, gk_geom->geo_int.bmag, true
  );
  gkyl_nodal_ops_m2n(
    n2m, &gk_geom->basis, &gk_geom->grid, &gk_geom->nrange_int, &gk_geom->local, 1,
    gk_geom->geo_int.B3_nodal, gk_geom->geo_int.B3, true
  );
  gkyl_nodal_ops_m2n(
    n2m, &gk_geom->basis, &gk_geom->grid, &gk_geom->nrange_int, &gk_geom->local, 3,
    gk_geom->geo_int.dualcurlbhat_nodal, gk_geom->geo_int.dualcurlbhat, true
  );

  // Populate nodal arrays for config space surface terms
  int lower[gk_geom->grid.ndim];
  int upper[gk_geom->grid.ndim];
  for (int dir = 0; dir < gk_geom->grid.ndim; dir++) {
    struct gk_geom_surf up_surf = gk_geom->geo_surf[dir];

    struct gkyl_range local_ext_in_dir;
    for (int i = 0; i < gk_geom->grid.ndim; i++) {
      lower[i] = gk_geom->local.lower[i];
      upper[i] = gk_geom->local.upper[i];
    }
    upper[dir] += 1;
    gkyl_sub_range_init(&local_ext_in_dir, &gk_geom->local_ext, lower, upper);

    gkyl_nodal_ops_m2n_surface(
      n2m, &gk_geom->surf_basis, &gk_geom->grid, &gk_geom->nrange_surf[dir], &local_ext_in_dir, 1,
      up_surf.bmag_nodal, up_surf.bmag, dir
    );
    gkyl_nodal_ops_m2n_surface(
      n2m, &gk_geom->surf_basis, &gk_geom->grid, &gk_geom->nrange_surf[dir], &local_ext_in_dir, 1,
      up_surf.jacobgeo_nodal, up_surf.jacobgeo, dir
    );
    gkyl_nodal_ops_m2n_surface(
      n2m, &gk_geom->surf_basis, &gk_geom->grid, &gk_geom->nrange_surf[dir], &local_ext_in_dir, 3,
      up_surf.b_i_nodal, up_surf.b_i, dir
    );
    gkyl_nodal_ops_m2n_surface(
      n2m, &gk_geom->surf_basis, &gk_geom->grid, &gk_geom->nrange_surf[dir], &local_ext_in_dir, 1,
      up_surf.cmag_nodal, up_surf.cmag, dir
    );
    gkyl_nodal_ops_m2n_surface(
      n2m, &gk_geom->surf_basis, &gk_geom->grid, &gk_geom->nrange_surf[dir], &local_ext_in_dir, 1,
      up_surf.jacobtot_inv_nodal, up_surf.jacobtot_inv, dir
    );
    gkyl_nodal_ops_m2n_surface(
      n2m, &gk_geom->surf_basis, &gk_geom->grid, &gk_geom->nrange_surf[dir], &local_ext_in_dir, 1,
      up_surf.B3_nodal, up_surf.B3, dir
    );
    gkyl_nodal_ops_m2n_surface(
      n2m, &gk_geom->surf_basis, &gk_geom->grid, &gk_geom->nrange_surf[dir], &local_ext_in_dir, 1,
      up_surf.normcurlbhat_nodal, up_surf.normcurlbhat, dir
    );
    gkyl_nodal_ops_m2n_surface(
      n2m, &gk_geom->surf_basis, &gk_geom->grid, &gk_geom->nrange_surf[dir], &local_ext_in_dir, 9,
      up_surf.normals_nodal, up_surf.normals, dir
    );
    gkyl_nodal_ops_m2n_surface(
      n2m, &gk_geom->surf_basis, &gk_geom->grid, &gk_geom->nrange_surf[dir], &local_ext_in_dir, 1,
      up_surf.lenr_nodal, up_surf.lenr, dir
    );
    gkyl_nodal_ops_m2n_surface(
      n2m, &gk_geom->surf_basis, &gk_geom->grid, &gk_geom->nrange_surf[dir], &local_ext_in_dir, 1,
      up_surf.deltats_nodal, up_surf.deltats, dir
    );
    gkyl_nodal_ops_m2n_surface(
      n2m, &gk_geom->surf_basis, &gk_geom->grid, &gk_geom->nrange_surf[dir], &local_ext_in_dir, 1,
      up_surf.bimpactangle_nodal, up_surf.bimpactangle, dir
    );
  }
  gkyl_nodal_ops_release(n2m);
}

