    case GKYL_BC_GK_SPECIES_REFLECT:
      bc_basic_type = GKYL_BC_DISTF_REFLECT;
      break;
    case GKYL_BC_GK_SPECIES_FIXED_FUNC:
      bc_basic_type = GKYL_BC_FIXED_FUNC;
      break;
    default:
      assert(false);
      break;
  }
  return bc_basic_type;
