      &up->grid, &up->local, &up->global, &up->nrange_surf[dir], 1, iter.idx[1],
      dir == 1 ? 1 : 2, dir != 1
    );
    double c = cos(theta), s = sin(theta);
    double bmag = gkyl_array_cfetch(geo->bmag_nodal, idx)[0];
    assert(bmag > 0.0);
    double *gij = gkyl_array_fetch(geo->g_ij_nodal, idx);
    gij[0] = gij[5] = 1.0;
    gij[1] = gij[2] = gij[4] = 0.0;
    gij[3] = r * r;
    double *tangent = gkyl_array_fetch(geo->dxdz_nodal, idx);
    tangent[0] = c;
    tangent[1] = s;
    tangent[2] = 0.0;
    tangent[3] = -r * s;
    tangent[4] = r * c;
    tangent[5] = 0.0;
    tangent[6] = tangent[7] = 0.0;
    tangent[8] = 1.0;
    double *dual = gkyl_array_fetch(geo->dzdx_nodal, idx);
    dual[0] = c;
    dual[1] = s;
    dual[2] = 0.0;
    dual[3] = r > 0.0 ? -s / r : 0.0;
    dual[4] = r > 0.0 ? c / r : 0.0;
    dual[5] = 0.0;
    dual[6] = dual[7] = 0.0;
    dual[8] = 1.0;
    double *dualmag = gkyl_array_fetch(geo->dualmag_nodal, idx);
    dualmag[0] = dualmag[2] = 1.0;
    dualmag[1] = r > 0.0 ? 1.0 / r : 0.0;
    double *normals = gkyl_array_fetch(geo->normals_nodal, idx);
    normals[0] = c;
    normals[1] = s;
    normals[2] = 0.0;
    normals[3] = -s;
    normals[4] = c;
    normals[5] = 0.0;
    normals[6] = normals[7] = 0.0;
    normals[8] = 1.0;
    gkyl_array_fetch(geo->jacobgeo_nodal, idx)[0] = r;
    double *bi = gkyl_array_fetch(geo->b_i_nodal, idx);
    bi[0] = bi[1] = 0.0;
    bi[2] = 1.0;
    double *bcart = gkyl_array_fetch(geo->bcart_nodal, idx);
    bcart[0] = bcart[1] = 0.0;
    bcart[2] = 1.0;
    gkyl_array_fetch(geo->cmag_nodal, idx)[0] = r * bmag;
    // 1/(JB) has no point value on the axis. The axis boundary updater never
    // samples this slot; zero is a finite sentinel for geometry output.
    gkyl_array_fetch(geo->jacobtot_inv_nodal, idx)[0] = r > 0.0 ? 1.0 / (r * bmag) : 0.0;
    gkyl_array_fetch(geo->B3_nodal, idx)[0] = bmag;
    gkyl_array_fetch(geo->lenr_nodal, idx)[0] = dir == 1 ? 1.0 : r;
    gkyl_array_fetch(geo->bimpactangle_nodal, idx)[0] = dir == 2 ? M_PI / 2.0 : 0.0;
    gkyl_array_fetch(geo->normcurlbhat_nodal, idx)[0] = 0.0;
    gkyl_array_fetch(geo->deltats_nodal, idx)[0] = 0.0;
  }
}

