#pragma once

#include <gkyl_mat_triples.h>
#include <gkyl_superlu.h>

// Object type
typedef struct gkyl_superlu_prob gkyl_superlu_prob;

/**
 * Create a new SuperLU Ax=B problem.
 * Create a new SuperLU A_i x_i = B_i where i \in {0,1,...,nprob-1},
 * for solving nprob linear problems. This module can be used in two ways:
 *   a) Using nprob=1 and nrhs>=1, so that one can solve nrhs linear problems
 *      with the same left-side matrix A_i for each problem, i.e. B is a matrix
 *      of nprob columns.
 *   b) Using nprob=>1 and nrhs=1, so we are solving nprob separate linear
 *      problems (each with a different left-side Matrix A_i, but with the same
 *      dimensions and sparsity pattern) where each problem only has a
 *      right-side vector with a single column.
 */
struct gkyl_superlu_prob *gkyl_superlu_prob_new(int nprob, int mrow, int ncol, int nrhs);

/**
 * Initialize SuperLU matrix A in Ax=B problem from a list of triples.
 *
 * @param prob SuperLu struct holding arrays used in problem.
 * @param tri coordinates & values of non-zero entries in A matrix (triplets).
 */
void gkyl_superlu_amat_from_triples(struct gkyl_superlu_prob *prob, struct gkyl_mat_triples **tri);

/**
 * Method to print the matrix A to screen.
 */
void gkyl_superlu_print_amat(struct gkyl_superlu_prob *prob);

/**
 * Perform the LU decomposition of the A matrix.
 * The _solve method will use these if they are pre-computed.
 */
void gkyl_superlu_ludecomp(struct gkyl_superlu_prob *prob);

/**
 * Initialize right-hand-side SuperLU matrix B in Ax=B problem from a list of
 * triples.
 *
 * @param prob SuperLu struct holding arrays used in problem.
 * @param tri coordinates & values of non-zero entries in B matrix (triplets).
 */
void gkyl_superlu_brhs_from_triples(struct gkyl_superlu_prob *prob, struct gkyl_mat_triples *tri);

/**
 * Initialize right-hand-side SuperLU matrix B in Ax=B problem from a simple
 * array. This is enough especially when solving a single Ax=B problem (with B
 * a vector) and makes the GPU interface implementation easier.
 *
 * @param prob SuperLu struct holding arrays used in problem.
 * @param bin column array for the right side source.
 */
void gkyl_superlu_brhs_from_array(struct gkyl_superlu_prob *prob, const double *bin);

/**
 * Solve Ax=B problem.
 *
 * @param prob SuperLu struct holding arrays used in problem.
 */
void gkyl_superlu_solve(struct gkyl_superlu_prob *prob);

/**
 * Update the values of the left-hand-side SuperLU matrix A in Ax=B problem from a list of
 * triples. Assumes the sparsity pattern didn't change.
 *
 * @param prob SuperLu struct holding arrays used in problem.
 * @param tri coordinates & values of non-zero entries in A matrix (triplets).
 */
void gkyl_superlu_amat_update_from_triples(
  struct gkyl_superlu_prob *prob, struct gkyl_mat_triples **tri
);

/**
 * Obtain the RHS ielement-th value of the jprob-th linear problem.
 * Recall the RHS is a mrow x nrhs matrix.
 *
 * @param linear index into the RHS flattened array for the desired value.
 * @return RHS value.
 */
double gkyl_superlu_get_rhs_ij(struct gkyl_superlu_prob *prob, long ielement, long jprob);

/**
 * Obtain the RHS value at location loc (a linear index into the RHS matrix).
 *
 * @param linear index into the RHS flattened array for the desired value.
 * @return RHS value.
 */
double gkyl_superlu_get_rhs_lin(struct gkyl_superlu_prob *prob, long loc);

double *gkyl_superlu_get_rhs_ptr(struct gkyl_superlu_prob *prob, long loc);

/**
 * Release SuperLU problem
 *
 * @param prob Pointer to SuperLU problem to release.
 */
void gkyl_superlu_prob_release(struct gkyl_superlu_prob *prob);
#include <gkyl_alloc.h>
#include <gkyl_mat_triples.h>
#include <gkyl_superlu_ops.h>

#include <stdbool.h>

struct gkyl_superlu_prob {
  SuperMatrix **A, **B; // matrices in A_j x_j = B_j problems.
  SuperMatrix **L, **U; // L and U factors in LU decomposition.
  double *rhs; // right-hand side entries.
  int *perm_c; // column permutation vector (re-used for each problem).
  int **perm_r; // row permutations from partial pivoting.
  int mrow, ncol; // A is a mrow x ncol matrix.
  int nnz; // number of non-zero entries in A.
  int nprob; // number of problems to solve (j=0,1,...,nprob-1).
  int nrhs; // number of columns of the RHS (B is an mrow x nrhs matrix).

  double **nzvals; // non-zero matrix elements.
  int **rowinds; // row index of entries in nzval.
  int **colptrs; // 1st entry of each column as index in nzval.

  int info, permc_spec;
  superlu_options_t options;
  SuperLUStat_t stat;
  trans_t trans;
  GlobalLU_t *Glu;
  // Arguments needed by the expert driver.
  double *R, *C;
  char equed;
  int *etree;
  double rpg, rcond;
  mem_usage_t mem_usage;
  double *ferr, *berr;
  void **work;
  int_t *lwork;
  bool LU_in_work;
};

gkyl_superlu_prob *
gkyl_superlu_prob_new(int nprob, int mrow, int ncol, int nrhs)
{
  assert((nprob == 1) || (nrhs == 1));

  struct gkyl_superlu_prob *prob = gkyl_malloc(sizeof(*prob));

  prob->nprob = nprob;
  prob->mrow = mrow;
  prob->ncol = ncol;
  prob->nrhs = nrhs;

  prob->A = gkyl_malloc(prob->nprob * sizeof(SuperMatrix *));
  prob->B = gkyl_malloc(prob->nprob * sizeof(SuperMatrix *));
  prob->L = gkyl_malloc(prob->nprob * sizeof(SuperMatrix *));
  prob->U = gkyl_malloc(prob->nprob * sizeof(SuperMatrix *));
  for (size_t k = 0; k < prob->nprob; k++) {
    prob->A[k] = gkyl_malloc(sizeof(SuperMatrix));
    prob->B[k] = gkyl_malloc(sizeof(SuperMatrix));
    prob->L[k] = gkyl_malloc(sizeof(SuperMatrix));
    prob->U[k] = gkyl_malloc(sizeof(SuperMatrix));
  }

  prob->rhs = doubleMalloc(mrow * GKYL_MAX2(nprob, nrhs));
  prob->perm_c = intMalloc(ncol);
  prob->perm_r = gkyl_malloc(prob->nprob * sizeof(int *));
  for (size_t k = 0; k < prob->nprob; k++) {
    prob->perm_r[k] = intMalloc(mrow);
  }

  prob->Glu = gkyl_malloc(prob->nprob * sizeof(GlobalLU_t));

  // Set the default input options.
  set_default_options(&prob->options);
  prob->options.ColPerm = NATURAL;
  // Disable equilibration: dgssvx would scale A in-place (equed='B'), but
  // gkyl_superlu_amat_update_from_triples writes raw values back into A's nzval.
  // A subsequent dgssvx with SamePattern and equed='B' would then treat those
  // raw values as already-scaled, factoring the wrong matrix. With Equil=NO,
  // equed stays 'N' across all calls so SamePattern works correctly.
  // Note that this may increase the condition number of A but it yields the same
  // result as the one observed on GPU see issue #1015.
  prob->options.Equil = NO;

  // Initialize the statistics variables.
  StatInit(&prob->stat);

  prob->trans = NOTRANS;

  // Create the RHS matrix B, with random data for now.
  for (size_t k = 0; k < mrow * GKYL_MAX2(nprob, nrhs); k++) {
    prob->rhs[k] = 1.0;
  }

  for (size_t k = 0; k < prob->nprob; k++) {
    dCreate_Dense_Matrix(
      prob->B[k], prob->mrow, prob->nrhs, &prob->rhs[k * prob->mrow], prob->mrow, SLU_DN, SLU_D,
      SLU_GE
    );
  }

  // Arguments needed by the expert driver.
  prob->equed = 'N';
  if (!(prob->etree = intMalloc(ncol))) {
    ABORT("superlu_ops: Malloc fails for etree[].");
  }
  if (!(prob->R = (double *)SUPERLU_MALLOC(mrow * sizeof(double)))) {
    ABORT("superlu_ops: Malloc fails for R[].");
  }
  if (!(prob->C = (double *)SUPERLU_MALLOC(ncol * sizeof(double)))) {
    ABORT("superlu_ops: Malloc fails for C[].");
  }
  if (!(prob->ferr = (double *)SUPERLU_MALLOC(nrhs * sizeof(double)))) {
    ABORT("superlu_ops: Malloc fails for ferr[].");
  }
  if (!(prob->berr = (double *)SUPERLU_MALLOC(nrhs * sizeof(double)))) {
    ABORT("superlu_ops: Malloc fails for berr[].");
  }

  prob->LU_in_work = false;
  prob->work = gkyl_malloc(prob->nprob * sizeof(void *));
  prob->lwork = gkyl_malloc(prob->nprob * sizeof(int));
  for (size_t k = 0; k < prob->nprob; k++) {
    prob->work[k] = 0;
    prob->lwork[k] = 0;
  }

  return prob;
}

