// Field data.
struct gk_field {
  struct gkyl_gyrokinetic_field info; // Data for field.

  enum gkyl_gkfield_id gkfield_id; // Field solver ID.
  enum gkyl_gyrokinetic_bc_type bc_par_phi; // Parallel BC to enforce on phi.

  bool update_field; // Are we updating the field?.
  bool calc_init_field; // Whether to compute the t=0 field.

  // Arrays for local charge density, global charge density, and global smoothed (in z) charge density.
  struct gkyl_array *rho_c;
  struct gkyl_array *rho_c_global_dg;
  struct gkyl_array *rho_c_global_smooth;
  struct gkyl_array *phi_fem, *phi_smooth; // Arrays for updates.

  struct gkyl_array *phi_host; // host copy for use IO and initialization

  bool init_phi_pol; // Whether to use the initial user polarization phi.
  struct gkyl_array *phi_pol; // Initial polarization density potential.

  struct gkyl_range global_sub_range; // sub range of intersection of global range and local range
  // for solving subset of Poisson solves with parallelization in z

  // organization of the different equation objects and the required data and solvers
  union {
    struct {
      struct gkyl_ambi_bolt_potential *ambi_pot;
      struct gkyl_array *sheath_vals[2 * GKYL_MAX_CDIM];
    };
    // EM GK model
    struct {
      struct gkyl_array *apar_fem; // array for A_parallel
      struct gkyl_array *apardot_fem; // array for d/dt A_parallel
    };
  };

  double es_energy_fac_1d;
  struct gkyl_array *es_energy_fac;
  bool is_dirichletvar; // Whether user provided spatially varying phi BCs.
  struct gkyl_array *phi_bc; // Spatially varying BC.
  struct gkyl_array *epsilon; // Polarization weight including geometric factors.
  struct gkyl_array *kSq; // Weight for Poisson/Helmholtz solver.

  struct gkyl_poisson_bias_line_list
    fem_parproj_bias_line_list; // Biased lines constraining the solution.

  struct gkyl_fem_parproj
    *fem_parproj; // Projects DG function onto continuous  FEM basis:  weight*phi_{fem} = phi_{dg}
  struct gkyl_fem_parproj *fem_parproj_rho_sol, *fem_parproj_phi_sol; // FEM projection in the SOL.
  struct gkyl_fem_parproj *fem_parproj_rho_core,
    *fem_parproj_phi_core; // FEM projection in the core.

  struct gkyl_fem_poisson_perp
    *fem_poisson_perp; // Solves - nabla . (epsilon * nabla phi) - kSq * phi = rho.

  // Objects needed for FLR effects.
  bool use_flr; // Whether to apply FLR effects.
  f->phi_fem = mkarr(app->use_gpu, app->basis.num_basis, app->global_ext.volume);
  f->phi_smooth = mkarr(app->use_gpu, app->basis.num_basis, app->local_ext.volume);

  // Allocate electromagnetic arrays if needed.
  if (f->gkfield_id == GKYL_GK_FIELD_EM) {
    f->apar_fem = mkarr(app->use_gpu, app->basis.num_basis, app->local_ext.volume);
    f->apardot_fem = mkarr(app->use_gpu, app->basis.num_basis, app->local_ext.volume);
  }

  // Allocate phi_host for I/O.
  f->phi_host = f->phi_smooth;
  if (app->use_gpu) {
    f->phi_host = mkarr(false, app->basis.num_basis, app->local_ext.volume);
  }

  if (f->gkfield_id == GKYL_GK_FIELD_ADIABATIC) {
    f->accumulate_rhoc_func = gk_field_accumulate_rho_c_adiabatic;
  } else {
    f->accumulate_rhoc_func = gk_field_accumulate_rho_c_poisson;
  }

  double polarization_weight = 0.0;
  double polarization_bmag = f->info.polarization_bmag ? f->info.polarization_bmag : app->bmag_ref;
  // Linearized polarization density
  for (int i = 0; i < app->num_species; ++i) {
    struct gk_species *s = &app->species[i];
    polarization_weight += s->info.polarization_density * s->info.mass / pow(polarization_bmag, 2);
  }
  // Allocate array for the polarization weight times geometric coefficients.
  f->epsilon =
    mkarr(app->use_gpu, (2 * (app->cdim / 3) + 1) * app->basis.num_basis, app->local_ext.volume);

  // Initialize the polarization weight.
  struct gkyl_array *Jgij[3] = {
    app->gk_geom->geo_int.gxxj, app->gk_geom->geo_int.gxyj, app->gk_geom->geo_int.gyyj
  };
  for (int i = 0; i < app->cdim - 2 / app->cdim; i++) {
    gkyl_array_set_offset(f->epsilon, polarization_weight, Jgij[i], i * app->basis.num_basis);
  }

  bool bc_is_np[GKYL_MAX_CDIM]; // Is the BC in this direction non-periodic?
  for (int d = 0; d < app->cdim; ++d) {
    bc_is_np[d] = true;
  }
  for (int d = 0; d < app->num_periodic_dir; ++d) {
    bc_is_np[app->periodic_dirs[d]] = false;
  }

  // Translate input file BCs into Poisson BCs.
  struct gkyl_poisson_bc poisson_bcs = {};
  for (int d = 0; d < app->cdim - 1; d++) {
    if (bc_is_np[d]) {
      struct gkyl_gyrokinetic_bc *bc_lo =
        gk_fetch_bc_with_dir_edge(f->info.poisson_bcs, 2 * app->cdim, d, GKYL_LOWER_EDGE);
      if (bc_lo != 0) {
        poisson_bcs.lo_type[d] = gkyl_gyrokinetic_translate_poisson_bc_type(bc_lo->type);
        for (int i = 0; i < 3; i++) {
          poisson_bcs.lo_value[d].v[i] = bc_lo->value[i];
        }
      }

      struct gkyl_gyrokinetic_bc *bc_up =
        gk_fetch_bc_with_dir_edge(f->info.poisson_bcs, 2 * app->cdim, d, GKYL_UPPER_EDGE);
      if (bc_up != 0) {
        poisson_bcs.up_type[d] = gkyl_gyrokinetic_translate_poisson_bc_type(bc_up->type);
        for (int i = 0; i < 3; i++) {
          poisson_bcs.up_value[d].v[i] = bc_up->value[i];
        }
      }
    } else {
      poisson_bcs.lo_type[d] =
        gkyl_gyrokinetic_translate_poisson_bc_type(GKYL_BC_GK_FIELD_PERIODIC);
      poisson_bcs.up_type[d] =
        gkyl_gyrokinetic_translate_poisson_bc_type(GKYL_BC_GK_FIELD_PERIODIC);
    }
  }

  // Initialize the Poisson solver.
  f->fem_poisson_perp = gkyl_fem_poisson_perp_new(
    &app->local, &app->grid, app->basis, &poisson_bcs, f->info.bias_line_list, f->epsilon, NULL,
    app->use_gpu
  );

  f->phi_bc = 0;
  f->is_dirichletvar = false;
  for (int i = 0; i < 2 * app->cdim; i++) {
    f->is_dirichletvar = f->is_dirichletvar ||
                         (f->info.poisson_bcs[i].type == GKYL_BC_GK_FIELD_DIRICHLET_VARYING ||
                          f->info.poisson_bcs[i].type == GKYL_BC_GK_FIELD_DIRICHLET_VARYING);
  }

