void
fem_poisson_perp_consteps_2x_check(
  struct fem_poisson_perp_consteps_objs *objs, int poly_order, struct gkyl_poisson_bc bcs,
  double scale_fac
)
{
  // Check results in fem_poisson_perp_consteps_2x test.

  if (poly_order == 1) {
    if (bcs.lo_type[0] == GKYL_POISSON_PERIODIC && bcs.up_type[0] == GKYL_POISSON_PERIODIC) {
      // Solution not yet verified for periodic 2x.
    } else if (bcs.lo_type[0] == GKYL_POISSON_DIRICHLET &&
               bcs.up_type[0] == GKYL_POISSON_DIRICHLET) {
      check_sol(
        &objs->localRange, objs->phi_ho, objs->basis.num_basis, get_sol_2x_p1_DxDx(), scale_fac, -1,
        -1, 1e-10
      );
    } else if (bcs.lo_type[0] == GKYL_POISSON_NEUMANN && bcs.up_type[0] == GKYL_POISSON_DIRICHLET) {
      check_sol(
        &objs->localRange, objs->phi_ho, objs->basis.num_basis, get_sol_2x_p1_NxDx(), scale_fac, -1,
        -1, 1e-10
      );
    } else if (bcs.lo_type[0] == GKYL_POISSON_DIRICHLET && bcs.up_type[0] == GKYL_POISSON_NEUMANN) {
      check_sol(
        &objs->localRange, objs->phi_ho, objs->basis.num_basis, get_sol_2x_p1_DxNx(), scale_fac, -1,
        -1, 1e-10
      );
    } else {
      TEST_CHECK(gkyl_compare(1., 2., 1e-10));
      TEST_MSG("This BC combination is not available");
    }
  } else {
    TEST_CHECK(gkyl_compare(1., 2., 1e-10));
    TEST_MSG("This poly_order is not available");
  }
}

