          up->kernels->bias_src_ker[keri](
            edge, bl->perp_dirs, bl->val, parProbOff, up->globalidx, brhs_p
          );
        }
      }
    }
  }
}

static void
fem_poisson_perp_alias_axis(gkyl_fem_poisson_perp *up)
{
  if (up->polar_axis) {
    for (int i = 0; i < up->num_basis; ++i) {
      up->globalidx[i] = up->axis_alias[up->globalidx[i]];
    }
  }
}

static void
fem_poisson_perp_pin_unused_axis_nodes(gkyl_fem_poisson_perp *up, long paridx)
{
  if (up->polar_axis) {
    for (long i = 0; i < up->numnodes_global; ++i) {
      if (up->axis_alias[i] != i) {
        gkyl_mat_triples_accum(up->tri[paridx], i, i, 1.0);
      }
    }
  }
}

static struct gkyl_fem_poisson_perp *
fem_poisson_perp_new(
  const struct gkyl_range *solve_range, const struct gkyl_rect_grid *grid,
  const struct gkyl_basis basis, struct gkyl_poisson_bc *bcs,
  struct gkyl_poisson_bias_line_list *bias_lines, struct gkyl_array *epsilon,
  struct gkyl_array *kSq, bool use_gpu, bool polar_axis
)
{
  struct gkyl_fem_poisson_perp *up = gkyl_malloc(sizeof(struct gkyl_fem_poisson_perp));
  up->polar_axis = polar_axis;
  up->axis_alias = 0;

  up->solve_range = solve_range;
  up->ndim = grid->ndim;
  up->ndim_perp = up->ndim - 1;
  up->grid = *grid;
  up->num_basis = basis.num_basis;
  up->basis_type = basis.b_type;
  up->poly_order = basis.poly_order;
  up->pardir = grid->ndim - 1; // Assume parallel direction is always the last.
  up->basis = basis;
  up->use_gpu = use_gpu;
  up->epsilon = gkyl_array_acquire(epsilon);

  assert(up->ndim > 1);
  assert(up->epsilon->ncomp == (2 * (up->ndim - 1) - 1) * basis.num_basis);

  // We assume epsilon and kSq live on the device, and we create a host-side
  // copies temporarily to compute the LHS matrix. This also works for CPU solves.
  struct gkyl_array *epsilon_ho =
    gkyl_array_new(GKYL_DOUBLE, up->epsilon->ncomp, up->epsilon->size);
  gkyl_array_copy(epsilon_ho, up->epsilon);
  struct gkyl_array *kSq_ho;
  if (kSq) {
    up->ishelmholtz = true;
    kSq_ho = gkyl_array_new(GKYL_DOUBLE, kSq->ncomp, kSq->size);
    gkyl_array_copy(kSq_ho, kSq);
  } else {
    up->ishelmholtz = false;
    kSq_ho = gkyl_array_new(GKYL_DOUBLE, up->num_basis, 1);
    gkyl_array_clear(kSq_ho, 0.0);

    up->kSq_null = use_gpu ? gkyl_array_cu_dev_new(GKYL_DOUBLE, kSq_ho->ncomp, kSq_ho->size) :
                             gkyl_array_acquire(kSq_ho);
    gkyl_array_clear(up->kSq_null, 0.0);
  }

  up->globalidx =
    gkyl_malloc(sizeof(long[up->num_basis])); // global index, one for each basis in a cell.

  for (int d = 0; d < up->ndim; d++) {
    up->num_cells[d] = up->solve_range->upper[d] - up->solve_range->lower[d] + 1;
  }

  // 2D range of perpendicular cells.
  gkyl_range_init(&up->perp_range2d, up->ndim_perp, up->solve_range->lower, up->solve_range->upper);
  // 1D range of parallel cells.
  int lower1d[] = {up->solve_range->lower[up->pardir]},
      upper1d[] = {up->solve_range->upper[up->pardir]};
  gkyl_range_init(&up->par_range1d, 1, lower1d, upper1d);

  // Range of perpendicular cells at each parallel location.
  up->perp_range =
    (struct gkyl_range *)gkyl_malloc(up->par_range1d.volume * sizeof(struct gkyl_range));
  gkyl_range_iter_init(&up->par_iter1d, &up->par_range1d);
  while (gkyl_range_iter_next(&up->par_iter1d)) {
    long paridx = gkyl_range_idx(&up->par_range1d, up->par_iter1d.idx);
    int removeDim[] = {0, 0, 0}, loc[] = {0, 0, 0};
    removeDim[up->pardir] = 1;
    loc[up->pardir] = paridx;
    gkyl_range_deflate(&up->perp_range[paridx], up->solve_range, removeDim, loc);
  }
  // Range of parallel cells.
  int sublower[GKYL_MAX_CDIM], subupper[GKYL_MAX_CDIM];
  for (int d = 0; d < up->ndim; d++) {
    sublower[d] = up->solve_range->lower[d];
    subupper[d] = up->solve_range->lower[d];
  }
  subupper[up->pardir] = up->solve_range->upper[up->pardir];
  gkyl_sub_range_init(&up->par_range, up->solve_range, sublower, subupper);

  // Prepare for periodic domain case.
  for (int d = 0; d < up->ndim_perp; d++) {
    // Sanity check.
    if ((bcs->lo_type[d] == GKYL_POISSON_PERIODIC && bcs->up_type[d] != GKYL_POISSON_PERIODIC) ||
        (bcs->lo_type[d] != GKYL_POISSON_PERIODIC && bcs->up_type[d] == GKYL_POISSON_PERIODIC)) {
      assert(false);
    }
  }
  for (int d = 0; d < up->ndim_perp; d++) {
    up->isdirperiodic[d] = bcs->lo_type[d] == GKYL_POISSON_PERIODIC;
  }
  up->isdomperiodic = true;
  for (int d = 0; d < up->ndim_perp; d++) {
    up->isdomperiodic = up->isdomperiodic && up->isdirperiodic[d];
  }
  //  assert(up->isdomperiodic == false);  // MF 2023/06/29: there's an error in
  //                                       // the periodic domain case I have not
  //                                       // solved.

  if (up->isdomperiodic) {
#ifdef GKYL_HAVE_CUDA
    if (up->use_gpu) {
      up->rhs_cellavg = gkyl_array_cu_dev_new(GKYL_DOUBLE, 1, epsilon->size);
      up->rhs_avg_cu = (double *)gkyl_cu_malloc(sizeof(double));
    } else {
      up->rhs_cellavg = gkyl_array_new(GKYL_DOUBLE, 1, epsilon->size);
    }
#else
    up->rhs_cellavg = gkyl_array_new(GKYL_DOUBLE, 1, epsilon->size);
#endif
    up->rhs_avg = (double *)gkyl_malloc(sizeof(double));
    gkyl_array_clear(up->rhs_cellavg, 0.0);
    // Factor accounting for normalization when subtracting a constant from a
    // DG field and the 1/N to properly compute the volume averaged RHS.
    up->mavgfac = -pow(sqrt(2.), up->ndim) / up->perp_range2d.volume;
  }

  // Pack BC values into a single array for easier use in kernels.
  for (int d = 0; d < up->ndim_perp; d++) {
    for (int k = 0; k < 6; k++) {
      up->bcvals[d * 2 * 3 + k] = 0.0; // default. Not used in some cases (e.g. periodic).
    }
    if (bcs->lo_type[d] != GKYL_POISSON_PERIODIC) {
      int vnum, voff;
      vnum = 1;
      voff = 2;
      for (int k = 0; k < vnum; k++) {
        up->bcvals[d * 2 * 3 + voff + k] = bcs->lo_value[d].v[k];
      }

      vnum = 1;
      voff = 2;
      for (int k = 0; k < vnum; k++) {
        up->bcvals[d * 2 * 3 + voff + 3 + k] = bcs->up_value[d].v[k];
      }
    }
  }
#ifdef GKYL_HAVE_CUDA
  if (up->use_gpu) {
    up->bcvals_cu = (double *)gkyl_cu_malloc(sizeof(double[PERP_DIM_MAX * 3 * 2]));
    gkyl_cu_memcpy(
      up->bcvals_cu, up->bcvals, sizeof(double[PERP_DIM_MAX * 3 * 2]), GKYL_CU_MEMCPY_H2D
    );
  }
#endif

  // Compute the number of local and global nodes.
  up->numnodes_local = up->num_basis;
  up->numnodes_global = gkyl_fem_poisson_perp_global_num_nodes(
    up->ndim, up->poly_order, basis.b_type, up->num_cells, up->isdirperiodic
  );

  if (polar_axis) {
    assert(!use_gpu && up->ndim == 3 && up->poly_order == 1);
    assert(up->num_cells[1] >= 2 && up->num_cells[1] % 2 == 0);
    assert(up->isdirperiodic[1] && !up->isdirperiodic[0]);
    assert(bcs->lo_type[0] == GKYL_POISSON_NEUMANN && bcs->lo_value[0].v[0] == 0.0);
    assert(!bias_lines || bias_lines->num_bias_line == 0);
    up->axis_alias = gkyl_malloc(up->numnodes_global * sizeof(long));
    for (long i = 0; i < up->numnodes_global; ++i) {
      up->axis_alias[i] = i;
    }
    int idx0[3] = {0, 0, 0};
    long first[8];
    up->kernels = gkyl_malloc(sizeof(struct gkyl_fem_poisson_perp_kernels));
    fem_poisson_perp_choose_local2global_kernels(&basis, up->isdirperiodic, up->kernels->l2g);
    up->kernels->l2g[0](up->num_cells, idx0, first);
    for (int ia = 0; ia < up->num_cells[1]; ++ia) {
      idx0[1] = ia;
      long ids[8];
      int keri = ia == up->num_cells[1] - 1 ? 2 : 0;
      up->kernels->l2g[keri](up->num_cells, idx0, ids);
      up->axis_alias[ids[0]] = first[0];
      up->axis_alias[ids[2]] = first[0];
      up->axis_alias[ids[4]] = first[4];
      up->axis_alias[ids[6]] = first[4];
    }
    gkyl_free(up->kernels);
  }

  for (int d = 0; d < up->ndim; d++) {
    up->dx[d] = up->grid.dx[d]; // Cell lengths.
  }
#ifdef GKYL_HAVE_CUDA
  if (up->use_gpu) {
    up->dx_cu = (double *)gkyl_cu_malloc(sizeof(double[GKYL_MAX_CDIM]));
    gkyl_cu_memcpy(up->dx_cu, up->dx, sizeof(double[GKYL_MAX_CDIM]), GKYL_CU_MEMCPY_H2D);
  }
#endif

  up->brhs = gkyl_array_new(
    GKYL_DOUBLE, 1, up->numnodes_global * up->par_range.volume
  ); // Global right side vector.

  up->kernels = gkyl_malloc(sizeof(struct gkyl_fem_poisson_perp_kernels));
#ifdef GKYL_HAVE_CUDA
  if (use_gpu) {
    up->kernels_cu = gkyl_cu_malloc(sizeof(struct gkyl_fem_poisson_perp_kernels));
  } else {
    up->kernels_cu = up->kernels;
  }
#else
  up->kernels_cu = up->kernels;
#endif

  // Select local-to-global mapping kernels:
  fem_poisson_perp_choose_local2global_kernels(&basis, up->isdirperiodic, up->kernels->l2g);

  // Select lhs kernels:
  fem_poisson_perp_choose_lhs_kernels(&basis, bcs, up->kernels->lhsker);

  // Select rhs src kernels:
  fem_poisson_perp_choose_src_kernels(&basis, bcs, up->kernels->srcker);

  // Select sol kernel:
  up->kernels->solker = fem_poisson_perp_choose_sol_kernels(&basis);

#ifdef GKYL_HAVE_CUDA
  if (up->use_gpu) {
    fem_poisson_perp_choose_kernels_cu(&basis, bcs, up->isdirperiodic, up->kernels_cu);
  }
#endif

  // Copy the biasing line list (bias_lines) into this updater.
  up->num_bias_line = 0;
  bool *bl_in_solve_range = 0;
  if (bias_lines) {
    if (bias_lines->num_bias_line > 0) {
      // Check if any bias lines are in solve_range, and copy their info into updater.
"}}}

item.stdout:
    } else {
      T_LU_lo.shift_func = app->gk_geom->lower_shift_func;
      T_LU_lo.shift_func_ctx = app->gk_geom->lower_shift_ctx;
    }
    gkf->bc_ts_lo = gkyl_bc_twistshift_inew(&T_LU_lo);

    long buff_sz =
      GKYL_MAX2(app->global_lower_ghost_par_sol.volume, app->global_lower_ghost_par_core.volume);
    gkf->bc_buffer = mkarr(app->use_gpu, app->basis.num_basis, buff_sz);

    gkf->gfss_bc_op_core_up = gkyl_bc_basic_gyrokinetic_new(
      par_dir, GKYL_UPPER_EDGE, GKYL_BC_GK_FIELD_BOUNDARY_VALUE, app->basis_on_dev,
      &app->global_upper_skin_par_core, &app->global_upper_ghost_par_core, app->basis.num_basis,
      app->cdim, app->use_gpu
    );
  }

  // Parallel smoother for the charge density.
  gkf->fem_parproj_rho_core = gkyl_fem_parproj_new(
    &app->global_core, &app->grid, &app->basis, fem_parproj_bc_rho_core, 0, 0, 0, app->use_gpu
  );
  gkf->fem_parproj_rho_sol = gkyl_fem_parproj_new(
    &app->global_sol, &app->grid, &app->basis, fem_parproj_bc_rho_sol, 0, 0, 0, app->use_gpu
  );

  // Fill bias line list for fem_parproj_phi.
  gk_field_2x3x_fill_fem_parproj_bias_lines(app, gkf, poisson_bcs);

  // Parallel smoother for the potential.
  gkf->fem_parproj_phi_core = gkyl_fem_parproj_new(
    &app->global_core, &app->grid, &app->basis, fem_parproj_bc_phi_core,
    &gkf->fem_parproj_bias_line_list, 0, 0, app->use_gpu
  );
  gkf->fem_parproj_phi_sol = gkyl_fem_parproj_new(
    &app->global_sol, &app->grid, &app->basis, fem_parproj_bc_phi_sol,
    &gkf->fem_parproj_bias_line_list, 0, 0, app->use_gpu
  );
}

static void
gk_field_rhs_poisson_perp_2x3x(struct gkyl_gyrokinetic_app *app, struct gk_field *field)
{
  // Smooth the charge density along z.
  field->fem_projection_par_rho_func(app, field, field->rho_c, field->rho_c);

  // Solve the Poisson equation.
  if (app->gk_geom->geometry_id == GKYL_GEOMETRY_CYLINDRICAL && app->use_gpu) {
    gkyl_array_copy(field->rho_host_axis, field->rho_c);
    gkyl_fem_poisson_perp_set_rhs(field->fem_poisson_perp, field->rho_host_axis);
    gkyl_fem_poisson_perp_solve(field->fem_poisson_perp, field->phi_host);
    gkyl_array_copy(field->phi_smooth, field->phi_host);
  } else {
    gkyl_fem_poisson_perp_set_rhs(field->fem_poisson_perp, field->rho_c);
    gkyl_fem_poisson_perp_solve(field->fem_poisson_perp, field->phi_smooth);
  }

  // Smooth the potential along z.
  field->fem_projection_par_phi_func(app, field, field->phi_smooth, field->phi_smooth);

  // Finish the Poisson solve with FLR effects.
  field->invert_flr(app, field, field->phi_smooth);
}

static void
gk_field_fem_release_2x3x(const gkyl_gyrokinetic_app *app, struct gk_field *f)
{
  gkyl_array_release(f->rho_c);
  gkyl_array_release(f->rho_c_global_dg);
  gkyl_array_release(f->rho_c_global_smooth);
  gkyl_array_release(f->phi_fem);
  gkyl_array_release(f->phi_smooth);

  if (f->gkfield_id == GKYL_GK_FIELD_EM) {
    gkyl_array_release(f->apar_fem);
    gkyl_array_release(f->apardot_fem);
  }

  if (app->use_gpu) {
    gkyl_array_release(f->phi_host);
  }

  gkyl_array_release(f->epsilon);
  if (f->epsilon_host_axis) {
    gkyl_array_release(f->epsilon_host_axis);
    gkyl_array_release(f->rho_host_axis);
  }

  gkyl_fem_poisson_perp_release(f->fem_poisson_perp);
  if (f->is_dirichletvar) {
    gkyl_array_release(f->phi_bc);
  }

  gkyl_fem_parproj_release(f->fem_parproj);

  gkyl_array_integrate_release(f->calc_em_energy);

  if (app->gk_geom->has_LCFS) {
    // Release updaters for solve with a LCFS/separatrix.
    gkyl_free(f->fem_parproj_bias_line_list.bl);
    gkyl_fem_parproj_release(f->fem_parproj_rho_core);
    gkyl_fem_parproj_release(f->fem_parproj_phi_core);
    gkyl_fem_parproj_release(f->fem_parproj_rho_sol);
    gkyl_fem_parproj_release(f->fem_parproj_phi_sol);

    if (app->cdim == 3) {
      gkyl_bc_twistshift_release(f->bc_ts_lo);
      gkyl_bc_basic_gyrokinetic_release(f->gfss_bc_op_core_up);
      gkyl_array_release(f->bc_buffer);
    }
  } else if (f->bc_par_phi == GKYL_BC_GK_FIELD_TWISTSHIFT) {
    // Release TS updaters.
    gkyl_free(f->fem_parproj_bias_line_list.bl);
    gkyl_fem_parproj_release(f->fem_parproj_rho_core);
    gkyl_fem_parproj_release(f->fem_parproj_phi_core);

    if (app->cdim == 3) {
      gkyl_bc_twistshift_release(f->bc_ts_lo);
      gkyl_bc_twistshift_release(f->bc_ts_up);
      gkyl_bc_basic_gyrokinetic_release(f->gfss_bc_op_core_up);
      gkyl_bc_basic_gyrokinetic_release(f->gfss_bc_op_core_lo);
      gkyl_array_release(f->bc_buffer);
    }
  }

  if (f->use_flr) {
    gk_field_flr_release(app, f);
  }
}

void
gk_field_fem_new_2x3x(struct gkyl_gyrokinetic_app *app, struct gk_field *f)
{
  // Create global subrange we'll copy the field solver solution from (into local).
  gkyl_sub_range_intersect(&f->global_sub_range, &app->global, &app->local);

  // Allocate arrays for charge density.
  f->rho_c = mkarr(app->use_gpu, app->basis.num_basis, app->local_ext.volume);
  f->rho_c_global_dg = mkarr(app->use_gpu, app->basis.num_basis, app->global_ext.volume);
  f->rho_c_global_smooth = mkarr(app->use_gpu, app->basis.num_basis, app->global_ext.volume);

  // Allocate arrays for electrostatic potential.
  f->phi_fem = mkarr(app->use_gpu, app->basis.num_basis, app->global_ext.volume);
  f->phi_smooth = mkarr(app->use_gpu, app->basis.num_basis, app->local_ext.volume);

  // Allocate electromagnetic arrays if needed.
  if (f->gkfield_id == GKYL_GK_FIELD_EM) {
    f->apar_fem = mkarr(app->use_gpu, app->basis.num_basis, app->local_ext.volume);
    f->apardot_fem = mkarr(app->use_gpu, app->basis.num_basis, app->local_ext.volume);
  }

  // Allocate phi_host for I/O.
  f->phi_host = f->phi_smooth;
  if (app->use_gpu) {
    f->phi_host = mkarr(false, app->basis.num_basis, app->local_ext.volume);
  }

  if (f->gkfield_id == GKYL_GK_FIELD_ADIABATIC) {
    f->accumulate_rhoc_func = gk_field_accumulate_rho_c_adiabatic;
  } else {
    f->accumulate_rhoc_func = gk_field_accumulate_rho_c_poisson;
  }

  double polarization_weight = 0.0;
  double polarization_bmag = f->info.polarization_bmag ? f->info.polarization_bmag : app->bmag_ref;
  // Linearized polarization density
  for (int i = 0; i < app->num_species; ++i) {
    struct gk_species *s = &app->species[i];
    polarization_weight += s->info.polarization_density * s->info.mass / pow(polarization_bmag, 2);
  }
  // Allocate array for the polarization weight times geometric coefficients.
  f->epsilon =
    mkarr(app->use_gpu, (2 * (app->cdim / 3) + 1) * app->basis.num_basis, app->local_ext.volume);
  f->epsilon_host_axis = 0;
  f->rho_host_axis = 0;

  // Initialize the polarization weight.
  struct gkyl_array *Jgij[3] = {
    app->gk_geom->geo_int.gxxj, app->gk_geom->geo_int.gxyj, app->gk_geom->geo_int.gyyj
  };
  for (int i = 0; i < app->cdim - 2 / app->cdim; i++) {
    gkyl_array_set_offset(f->epsilon, polarization_weight, Jgij[i], i * app->basis.num_basis);
  }

  bool bc_is_np[GKYL_MAX_CDIM]; // Is the BC in this direction non-periodic?
  for (int d = 0; d < app->cdim; ++d) {
    bc_is_np[d] = true;
  }
  for (int d = 0; d < app->num_periodic_dir; ++d) {
    bc_is_np[app->periodic_dirs[d]] = false;
  }

  // Translate input file BCs into Poisson BCs.
  struct gkyl_poisson_bc poisson_bcs = {};
  for (int d = 0; d < app->cdim - 1; d++) {
    if (bc_is_np[d]) {
      struct gkyl_gyrokinetic_bc *bc_lo =
        gk_fetch_bc_with_dir_edge(f->info.poisson_bcs, 2 * app->cdim, d, GKYL_LOWER_EDGE);
      if (bc_lo != 0) {
        poisson_bcs.lo_type[d] = gkyl_gyrokinetic_translate_poisson_bc_type(bc_lo->type);
        for (int i = 0; i < 3; i++) {
          poisson_bcs.lo_value[d].v[i] = bc_lo->value[i];
        }
      }

      struct gkyl_gyrokinetic_bc *bc_up =
        gk_fetch_bc_with_dir_edge(f->info.poisson_bcs, 2 * app->cdim, d, GKYL_UPPER_EDGE);
      if (bc_up != 0) {
        poisson_bcs.up_type[d] = gkyl_gyrokinetic_translate_poisson_bc_type(bc_up->type);
        for (int i = 0; i < 3; i++) {
          poisson_bcs.up_value[d].v[i] = bc_up->value[i];
        }
      }
    } else {
      poisson_bcs.lo_type[d] =
        gkyl_gyrokinetic_translate_poisson_bc_type(GKYL_BC_GK_FIELD_PERIODIC);
      poisson_bcs.up_type[d] =
        gkyl_gyrokinetic_translate_poisson_bc_type(GKYL_BC_GK_FIELD_PERIODIC);
    }
  }

  // Initialize the Poisson solver.
  if (app->gk_geom->geometry_id == GKYL_GEOMETRY_CYLINDRICAL) {
    struct gkyl_gyrokinetic_bc *axis_bc =
      gk_fetch_bc_with_dir_edge(f->info.poisson_bcs, 2 * app->cdim, 0, GKYL_LOWER_EDGE);
    assert(axis_bc && axis_bc->type == GKYL_BC_GK_FIELD_AXIS);
    struct gkyl_array *epsilon_axis = f->epsilon;
    if (app->use_gpu) {
      f->epsilon_host_axis = mkarr(false, f->epsilon->ncomp, f->epsilon->size);
      f->rho_host_axis = mkarr(false, app->basis.num_basis, app->local_ext.volume);
      gkyl_array_copy(f->epsilon_host_axis, f->epsilon);
      epsilon_axis = f->epsilon_host_axis;
    }
    f->fem_poisson_perp = gkyl_fem_poisson_perp_cylindrical_new(
      &app->local, &app->grid, app->basis, &poisson_bcs, epsilon_axis
    );
  } else {
