        case GKYL_BC_GK_SPECIES_COPY:
        case GKYL_BC_GK_SPECIES_REFLECT:
        case GKYL_BC_GK_SPECIES_ABSORB:
          gkyl_bc_basic_gyrokinetic_advance(species->bc_up[d], species->bc_buffer, f);
