static void
polar_epsilon(double t, const double *xc, double *out, void *ctx)
{
  out[0] = xc[0];
  out[1] = 0.0;
  out[2] = 1.0 / xc[0];
}

static void
polar_source(double t, const double *xc, double *out, void *ctx)
{
  out[0] = xc[0];
}

static void
polar_source_mode1(double t, const double *xc, double *out, void *ctx)
{
  out[0] = 8.0 * xc[0] * xc[0] * cos(xc[1]);
}

static double
run_axis_poisson(bool mode1, int nr)
{
  struct gkyl_basis basis;
  gkyl_cart_modal_serendip(&basis, 3, 1);
  struct gkyl_rect_grid grid;
  double lower[3] = {0.0, -M_PI, -1.0};
  double upper[3] = {1.0, M_PI, 1.0};
  int cells[3] = {nr, 2 * nr, 2};
  gkyl_rect_grid_init(&grid, 3, lower, upper, cells);
  struct gkyl_range local, ext;
  int nghost[3] = {1, 1, 1};
  gkyl_create_grid_ranges(&grid, nghost, &ext, &local);

  struct gkyl_array *epsilon = gkyl_array_new(GKYL_DOUBLE, 3 * basis.num_basis, ext.volume);
  struct gkyl_array *rhs = gkyl_array_new(GKYL_DOUBLE, basis.num_basis, ext.volume);
  struct gkyl_array *phi = gkyl_array_new(GKYL_DOUBLE, basis.num_basis, ext.volume);
  gkyl_proj_on_basis *projector = gkyl_proj_on_basis_new(&grid, &basis, 2, 3, polar_epsilon, NULL);
  gkyl_proj_on_basis_advance(projector, 0.0, &local, epsilon);
  gkyl_proj_on_basis_release(projector);
  projector =
    gkyl_proj_on_basis_new(&grid, &basis, 2, 1, mode1 ? polar_source_mode1 : polar_source, NULL);
  gkyl_proj_on_basis_advance(projector, 0.0, &local, rhs);
  gkyl_proj_on_basis_release(projector);

  struct gkyl_poisson_bc bcs = {};
  bcs.lo_type[0] = GKYL_POISSON_NEUMANN;
  bcs.up_type[0] = GKYL_POISSON_DIRICHLET;
  bcs.lo_type[1] = bcs.up_type[1] = GKYL_POISSON_PERIODIC;
  struct gkyl_fem_poisson_perp *solver =
    gkyl_fem_poisson_perp_cylindrical_new(&local, &grid, basis, &bcs, epsilon);
  gkyl_fem_poisson_perp_set_rhs(solver, rhs);
  gkyl_fem_poisson_perp_solve(solver, phi);

  double axis_value = 0.0;
  for (int ia = 0; ia < cells[1]; ++ia) {
    int idx[3] = {local.lower[0], local.lower[1] + ia, local.lower[2]};
    const double *coeff = gkyl_array_cfetch(phi, gkyl_range_idx(&ext, idx));
    double left[3] = {-1.0, -1.0, 0.0};
    double right[3] = {-1.0, 1.0, 0.0};
    double value_left = basis.eval_expand(left, coeff);
    double value_right = basis.eval_expand(right, coeff);
    TEST_CHECK(fabs(value_left - value_right) < 1e-10);
    if (ia == 0) {
      axis_value = value_left;
    } else {
      TEST_CHECK(fabs(value_left - axis_value) < 1e-10);
    }
  }
  TEST_CHECK(fabs(axis_value - (mode1 ? 0.0 : 0.25)) < 0.03);
  TEST_MSG("axis potential %.17g", axis_value);
  double errsq = 0.0, normsq = 0.0;
  for (int ir = 0; ir < nr; ++ir) {
    double r = (ir + 0.5) * grid.dx[0];
    for (int ia = 0; ia < cells[1]; ++ia) {
      int idx[3] = {local.lower[0] + ir, local.lower[1] + ia, local.lower[2]};
      const double *coeff = gkyl_array_cfetch(phi, gkyl_range_idx(&ext, idx));
      double center[3] = {0.0, 0.0, 0.0};
      double theta = grid.lower[1] + (ia + 0.5) * grid.dx[1];
      double expected = mode1 ? (r - r * r * r) * cos(theta) : (1.0 - r * r) / 4.0;
      double error = basis.eval_expand(center, coeff) - expected;
      errsq += r * error * error;
      normsq += r * expected * expected;
    }
  }

  gkyl_fem_poisson_perp_release(solver);
  gkyl_array_release(phi);
  gkyl_array_release(rhs);
  gkyl_array_release(epsilon);
  return sqrt(errsq / normsq);
}

static void
test_axis_poisson(void)
{
  double coarse = run_axis_poisson(false, 8);
  double fine = run_axis_poisson(false, 16);
  TEST_CHECK(fine < coarse);
  TEST_MSG("axisymmetric relative errors: coarse %.17g, fine %.17g", coarse, fine);
}

static void
test_axis_poisson_mode1(void)
{
  double coarse = run_axis_poisson(true, 8);
  double fine = run_axis_poisson(true, 16);
  TEST_CHECK(fine < coarse);
  TEST_MSG("mode-1 relative errors: coarse %.17g, fine %.17g", coarse, fine);
}

TEST_LIST = {
  {"axis_poisson", test_axis_poisson},
  {"axis_poisson_mode1", test_axis_poisson_mode1},
  {NULL, NULL}
};
