+static void
+gk_species_apply_axis_bc(struct gk_species *species, struct gkyl_array *f)
+{
+  struct gkyl_array *host = f;
+  if (gkyl_array_is_cu_dev(f)) {
+    host = gkyl_array_new(f->type, f->ncomp, f->size);
+    gkyl_array_copy(host, f);
+  }
+
+  int ntheta = species->grid.cells[1];
+  assert(ntheta > 0 && ntheta % 2 == 0);
+  assert(f->ncomp % species->basis.num_basis == 0);
+  struct gkyl_range_iter iter;
+  gkyl_range_iter_init(&iter, &species->local_lower_ghost[0]);
+  while (gkyl_range_iter_next(&iter)) {
+    int src_idx[GKYL_MAX_DIM];
+    for (int d = 0; d < species->basis.ndim; ++d) {
+      src_idx[d] = iter.idx[d];
+    }
+    src_idx[0] = 2 * species->local.lower[0] - 1 - iter.idx[0];
+    src_idx[1] =
+      species->local.lower[1] + (iter.idx[1] - species->local.lower[1] + ntheta / 2) % ntheta;
+    long src = gkyl_range_idx(&species->local_ext, src_idx);
+    long dst = gkyl_range_idx(&species->local_ext, iter.idx);
+    const double *src_f = gkyl_array_cfetch(host, src);
+    double *dst_f = gkyl_array_fetch(host, dst);
+    for (int k = 0; k < f->ncomp; k += species->basis.num_basis) {
+      species->basis.flip_odd_sign(0, src_f + k, dst_f + k);
+    }
+  }
+
+  if (host != f) {
+    gkyl_array_copy(f, host);
+    gkyl_array_release(host);
+  }
+}
