    double alpha_curr_mapped;
    position_map->maps[1](0.0, &alpha_curr, &alpha_curr_mapped, position_map->ctxs[1]);
    alpha_curr = alpha_curr_mapped;
    for (int ip = nrange->lower[PSI_IDX]; ip <= nrange->upper[PSI_IDX]; ++ip) {
      double psi_curr = gk_geometry_node_coord(
        &up->grid, &up->local, &up->global, nrange, 0, ip, up->basis.poly_order, false
      );
      double psi_curr_mapped;
      position_map->maps[0](0.0, &psi_curr, &psi_curr_mapped, position_map->ctxs[0]);
      psi_curr = psi_curr_mapped;
      cidx[PSI_IDX] = ip;
      // set node coordinates
      for (int it = nrange->lower[TH_IDX]; it <= nrange->upper[TH_IDX]; ++it) {
        double theta_curr = gk_geometry_node_coord(
          &up->grid, &up->local, &up->global, nrange, 2, it, up->basis.poly_order, false
        );
        double theta_curr_mapped;
        position_map->maps[2](0.0, &theta_curr, &theta_curr_mapped, position_map->ctxs[2]);
        theta_curr = theta_curr_mapped;
        cidx[TH_IDX] = it;

        double *mc2p_n =
          (double *)gkyl_array_fetch(up->geo_corn.mc2p_nodal, gkyl_range_idx(nrange, cidx));
        double *bmag_n =
          (double *)gkyl_array_fetch(up->geo_corn.bmag_nodal, gkyl_range_idx(nrange, cidx));
        double xyz[3] = {psi_curr, alpha_curr, theta_curr};
        double XYZ[3] = {0.};
        double B[3] = {0.};
        mapc2p_func(0.0, xyz, XYZ, mapc2p_ctx);
        bfield_func(0.0, xyz, B, bfield_ctx);

        mc2p_n[X_IDX] = XYZ[X_IDX];
        mc2p_n[Y_IDX] = XYZ[Y_IDX];
        mc2p_n[Z_IDX] = XYZ[Z_IDX];
        bmag_n[0] = sqrt(B[0] * B[0] + B[1] * B[1] + B[2] * B[2]);

        double *mc2nu_n =
          gkyl_array_fetch(up->geo_corn.mc2nu_pos_nodal, gkyl_range_idx(nrange, cidx));
        mc2nu_n[X_IDX] = psi_curr;
        mc2nu_n[Y_IDX] = alpha_curr;
        mc2nu_n[Z_IDX] = theta_curr;
      }
    }
  }

  struct gkyl_nodal_ops *n2m = gkyl_nodal_ops_new(&up->basis, &up->grid, false);
  gkyl_nodal_ops_n2m(
    n2m, &up->basis, &up->grid, nrange, &up->local, 3, up->geo_corn.mc2p_nodal, up->geo_corn.mc2p,
    false
  );
  gkyl_nodal_ops_n2m(
    n2m, &up->basis, &up->grid, nrange, &up->local, 3, up->geo_corn.mc2nu_pos_nodal,
    up->geo_corn.mc2nu_pos, false
  );
  gkyl_nodal_ops_n2m(
    n2m, &up->basis, &up->grid, nrange, &up->local, 1, up->geo_corn.bmag_nodal, up->geo_corn.bmag,
    false
  );
  gkyl_nodal_ops_release(n2m);

  // Need 1/B for LBO collisions, computed weakly.
  gkyl_dg_inv_op_range(&up->basis, 0, up->geo_corn.bmag_inv, 0, up->geo_corn.bmag, &up->local);
}

static void
gk_geometry_mapc2p_advance_interior(
  struct gk_geometry *up, struct gkyl_range *nrange, double dzc[3], evalf_t mapc2p_func,
  void *mapc2p_ctx, evalf_t bfield_func, void *bfield_ctx, struct gkyl_position_map *position_map
)
{
  //Now project mapc2p and the FD array
  enum { PSI_IDX, AL_IDX, TH_IDX }; // arrangement of computational coordinates
  enum { X_IDX, Y_IDX, Z_IDX }; // arrangement of cartesian coordinates

  double dtheta = up->grid.dx[TH_IDX], dpsi = up->grid.dx[PSI_IDX], dalpha = up->grid.dx[AL_IDX];

  // used for finite differences
  double delta_alpha = dalpha * 1e-2;
  double delta_psi = dpsi * 1e-2;
  double delta_theta = dtheta * 1e-2;
  dzc[0] = delta_psi;
  dzc[1] = delta_alpha;
  dzc[2] = delta_theta;
  int modifiers[5] = {0, -1, 1, -2, 2};

  int cidx[3] = {0};
  for (int ia = nrange->lower[AL_IDX]; ia <= nrange->upper[AL_IDX]; ++ia) {
    cidx[AL_IDX] = ia;
    for (int ia_delta = 0; ia_delta < 3; ia_delta++) { // interior stencil
      double alpha_curr =
        gk_geometry_node_coord(
          &up->grid, &up->local, &up->global, nrange, 1, ia, up->basis.poly_order + 1, true
        ) +
        modifiers[ia_delta] * delta_alpha;
      double alpha_curr_mapped;
      position_map->maps[1](0.0, &alpha_curr, &alpha_curr_mapped, position_map->ctxs[1]);
      alpha_curr = alpha_curr_mapped;

      for (int ip = nrange->lower[PSI_IDX]; ip <= nrange->upper[PSI_IDX]; ++ip) {
        int ip_delta_max = 3; // interior
        if (ia_delta != 0) {
          ip_delta_max = 1;
        }
        for (int ip_delta = 0; ip_delta < ip_delta_max; ip_delta++) {
          double psi_curr =
            gk_geometry_node_coord(
              &up->grid, &up->local, &up->global, nrange, 0, ip, up->basis.poly_order + 1, true
            ) +
            modifiers[ip_delta] * delta_psi;
          double psi_curr_mapped;
          position_map->maps[0](0.0, &psi_curr, &psi_curr_mapped, position_map->ctxs[0]);
          psi_curr = psi_curr_mapped;
          cidx[PSI_IDX] = ip;
          // set node coordinates
          for (int it = nrange->lower[TH_IDX]; it <= nrange->upper[TH_IDX]; ++it) {
            int it_delta_max = 3; // interior
            if (ia_delta != 0 || ip_delta != 0) {
              it_delta_max = 1;
            }
            for (int it_delta = 0; it_delta < it_delta_max; it_delta++) {
              double theta_curr =
                gk_geometry_node_coord(
                  &up->grid, &up->local, &up->global, nrange, 2, it, up->basis.poly_order + 1, true
                ) +
                modifiers[it_delta] * delta_theta;
              double theta_curr_mapped;
              position_map->maps[2](0.0, &theta_curr, &theta_curr_mapped, position_map->ctxs[2]);
              theta_curr = theta_curr_mapped;

              cidx[TH_IDX] = it;
              int lidx = 0;
              if (ip_delta != 0) {
                lidx = 3 + 3 * (ip_delta - 1);
              }
              if (ia_delta != 0) {
                lidx = 15 + 3 * (ia_delta - 1);
              }
              if (it_delta != 0) {
                lidx = 27 + 3 * (it_delta - 1);
              }

              double *mc2p_quad_fd_n =
                (double *)gkyl_array_fetch(up->geo_int.mc2p_nodal_fd, gkyl_range_idx(nrange, cidx));
              double *mc2p_quad_n =
                (double *)gkyl_array_fetch(up->geo_int.mc2p_nodal, gkyl_range_idx(nrange, cidx));
              double *bmag_n =
                (double *)gkyl_array_fetch(up->geo_int.bmag_nodal, gkyl_range_idx(nrange, cidx));
              double *bhat_quad_fd_n =
                (double *)gkyl_array_fetch(up->geo_int.b_i_nodal_fd, gkyl_range_idx(nrange, cidx));

              double xyz[3] = {psi_curr, alpha_curr, theta_curr};
              double XYZ[3] = {0.};
              double B[3] = {0.};
              mapc2p_func(0.0, xyz, XYZ, mapc2p_ctx);
              bfield_func(0.0, xyz, B, bfield_ctx);

              mc2p_quad_fd_n[lidx + X_IDX] = XYZ[X_IDX];
              mc2p_quad_fd_n[lidx + Y_IDX] = XYZ[Y_IDX];
              mc2p_quad_fd_n[lidx + Z_IDX] = XYZ[Z_IDX];

              double bmag = sqrt(B[0] * B[0] + B[1] * B[1] + B[2] * B[2]);
              bhat_quad_fd_n[lidx + X_IDX] = B[X_IDX] / bmag;
              bhat_quad_fd_n[lidx + Y_IDX] = B[Y_IDX] / bmag;
              bhat_quad_fd_n[lidx + Z_IDX] = B[Z_IDX] / bmag;

