                mc2p_quad_n[Y_IDX] = XYZ[Y_IDX];
                mc2p_quad_n[Z_IDX] = XYZ[Z_IDX];
                bmag_n[0] = bmag;
              }
            }
          }
        }
      }
    }
  }

  struct gkyl_nodal_ops *n2m = gkyl_nodal_ops_new(&up->basis, &up->grid, false);
  gkyl_nodal_ops_n2m(
