void
gkyl_gk_dg_geom_populate_surf(
  struct gkyl_dg_geom *dg_geom, struct gkyl_gk_dg_geom *gk_dg_geom, struct gk_geometry *gk_geom
)
{
  int ndim = gk_geom->grid.ndim;
  // Populate surface nodes
  for (int dir = 0; dir < ndim; dir++) {
    struct gkyl_range local_ext_in_dir;
    int lower[3] = {gk_geom->local.lower[0], gk_geom->local.lower[1], gk_geom->local.lower[2]};
    int upper[3] = {gk_geom->local.upper[0], gk_geom->local.upper[1], gk_geom->local.upper[2]};
    upper[dir] += 1;
    gkyl_sub_range_init(&local_ext_in_dir, &gk_geom->local_ext, lower, upper);

    struct gkyl_range_iter iter;
    gkyl_range_iter_init(&iter, &local_ext_in_dir);
    while (gkyl_range_iter_next(&iter)) {
      long loc = gkyl_range_idx(&local_ext_in_dir, iter.idx);
      struct gkyl_dg_surf_geom *dgs = gkyl_array_fetch(dg_geom->surf_geom[dir], loc);
      struct gkyl_gk_dg_surf_geom *gkdgs = gkyl_array_fetch(gk_dg_geom->surf_geom[dir], loc);

      struct gkyl_range_iter qsiter;
      gkyl_range_iter_init(&qsiter, &dg_geom->surf_quad_range);
      int global_nodal_idx[ndim];
      while (gkyl_range_iter_next(&qsiter)) {
        int count = 0;
        for (int d = 0; d < ndim; ++d) {
          global_nodal_idx[d] = d == dir ?
                                  iter.idx[d] - gk_geom->local.lower[d] :
                                  (iter.idx[d] - gk_geom->local.lower[d]) * 2 + qsiter.idx[count];
          if (d != dir) {
            count += 1;
          }
        }
        long qsloc = gkyl_range_idx(&dg_geom->surf_quad_range, qsiter.idx);
        long global_loc = gkyl_range_idx(&gk_geom->nrange_surf[dir], global_nodal_idx);

        // set lenr
        const double *global_val = gkyl_array_cfetch(gk_geom->geo_surf[dir].lenr_nodal, global_loc);
        dgs[qsloc].area_elem = global_val[0];

        // set normals
        global_val = gkyl_array_cfetch(gk_geom->geo_surf[dir].normals_nodal, global_loc);
        dgs[qsloc].norm.x[0] = global_val[dir * 3 + 0];
        dgs[qsloc].norm.x[1] = global_val[dir * 3 + 1];
        dgs[qsloc].norm.x[2] = global_val[dir * 3 + 2];

        // set e3hat \dot B = B^3/sqrt(g_33}
        global_val = gkyl_array_cfetch(gk_geom->geo_surf[dir].B3_nodal, global_loc);
        gkdgs[qsloc].B3 = global_val[0];
        // set n \dot curl(bhat)
        global_val = gkyl_array_cfetch(gk_geom->geo_surf[dir].normcurlbhat_nodal, global_loc);
        gkdgs[qsloc].normcurlbhat = global_val[0];

        // set |B|
        global_val = gkyl_array_cfetch(gk_geom->geo_surf[dir].bmag_nodal, global_loc);
        gkdgs[qsloc].bmag = global_val[0];

        // set Jacobgeo
        global_val = gkyl_array_cfetch(gk_geom->geo_surf[dir].jacobgeo_nodal, global_loc);
        gkdgs[qsloc].Jc = global_val[0];

        // set bhat
        global_val = gkyl_array_cfetch(gk_geom->geo_surf[dir].b_i_nodal, global_loc);
        gkdgs[qsloc].bhat.x[0] = global_val[0];
        gkdgs[qsloc].bhat.x[1] = global_val[1];
        gkdgs[qsloc].bhat.x[2] = global_val[2];
      }
{
#ifdef GKYL_HAVE_CUDA
  if (up->use_gpu) {
    gkyl_hyper_dg_advance_cu(up, update_range, fIn, cflrate, rhs);
    return;
  }
#endif

  int ndim = up->ndim;
  int idxl[GKYL_MAX_DIM], idxc[GKYL_MAX_DIM], idxr[GKYL_MAX_DIM], idx_edge[GKYL_MAX_DIM];
  double xcl[GKYL_MAX_DIM], xcc[GKYL_MAX_DIM], xcr[GKYL_MAX_DIM], xc_edge[GKYL_MAX_DIM];
  // integer used for selecting between left-edge zero-flux BCs and right-edge zero-flux BCs
  int edge;

  struct gkyl_range_iter iter;
  gkyl_range_iter_init(&iter, update_range);
  while (gkyl_range_iter_next(&iter)) {
    gkyl_copy_int_arr(ndim, iter.idx, idxc);
    gkyl_rect_grid_cell_center(&up->grid, idxc, xcc);

    long linc = gkyl_range_idx(update_range, idxc);
    if (up->update_vol_term) {
      double cflr = up->equation->vol_term(
        up->equation, xcc, up->grid.dx, idxc, gkyl_array_cfetch(fIn, linc),
        gkyl_array_fetch(rhs, linc)
      );
      double *cflrate_d = gkyl_array_fetch(cflrate, linc);
      cflrate_d[0] += cflr; // frequencies are additive
    }

    for (int d = 0; d < up->num_up_dirs; ++d) {
      int dir = up->update_dirs[d];
      double cfls = 0.0;
      // Assumes update_range owns lower and upper edges of the domain
      if ((up->zero_flux_flags[dir] && idxc[dir] == update_range->lower[dir]) ||
          (up->zero_flux_flags[dir + ndim] && idxc[dir] == update_range->upper[dir])) {
        gkyl_copy_int_arr(ndim, iter.idx, idx_edge);
        edge = (idxc[dir] == update_range->lower[dir]) ? -1 : 1;
        // idx_edge stores interior edge index (first index away from skin cell)
        idx_edge[dir] = idx_edge[dir] - edge;

        gkyl_rect_grid_cell_center(&up->grid, idx_edge, xc_edge);
        long lin_edge = gkyl_range_idx(update_range, idx_edge);

        cfls = up->equation->boundary_surf_term(
          up->equation, dir, xc_edge, xcc, up->grid.dx, up->grid.dx, idx_edge, idxc, edge,
          gkyl_array_cfetch(fIn, lin_edge), gkyl_array_cfetch(fIn, linc),
          gkyl_array_fetch(rhs, linc)
        );
      } else {
        gkyl_copy_int_arr(ndim, iter.idx, idxl);
        gkyl_copy_int_arr(ndim, iter.idx, idxr);
        idxl[dir] = idxl[dir] - 1;
        idxr[dir] = idxr[dir] + 1;

        gkyl_rect_grid_cell_center(&up->grid, idxl, xcl);
        gkyl_rect_grid_cell_center(&up->grid, idxr, xcr);
        long linl = gkyl_range_idx(update_range, idxl);
        long linr = gkyl_range_idx(update_range, idxr);

        cfls = up->equation->surf_term(
          up->equation, dir, xcl, xcc, xcr, up->grid.dx, up->grid.dx, up->grid.dx, idxl, idxc, idxr,
          gkyl_array_cfetch(fIn, linl), gkyl_array_cfetch(fIn, linc), gkyl_array_cfetch(fIn, linr),
          gkyl_array_fetch(rhs, linc)
        );
      }
      double *cflrate_d = gkyl_array_fetch(cflrate, linc);
      cflrate_d[0] += cfls; // frequencies are additive
    }
  }
}

