#include <stdio.h>
#include <math.h>
#include <gkyl_gk_collisionless_flux_kernels.h>

int main(void)
{
  struct gkyl_dg_surf_geom dgs[4] = {0};
  struct gkyl_gk_dg_surf_geom gkdgs[4] = {0};
  for (int i=0; i<4; ++i) {
    gkdgs[i].bmag = gkdgs[i].B3 = 1.0;
    gkdgs[i].bhat.x[2] = 1.0;
  }
  double w[5] = {0}, dx[5] = {1,1,1,1,1};
  double vmap[4] = {0,1,1,1}, vmapSq[3] = {1,1,1};
  double bmag[8] = {2.8284271247461903}, ratio[8] = {2.8284271247461903};
  double phi[8] = {0}, f[48] = {1}, flux[128] = {0};
  double cfl = gk_collisionless_flux_surfx_3x2v_ser_p1(
    w, dx, vmap, vmapSq, 1, 1, dgs, gkdgs, bmag, ratio, ratio, phi, f, f, flux);
  int bad = 0;
  for (int i=0; i<24; ++i) bad += !isfinite(flux[i]);
  printf("axis: nonfinite radial flux slots = %d/24, cfl = %.17g\n", bad, cfl);
  for (int i=0; i<4; ++i) dgs[i].area_elem = gkdgs[i].Jc = 1.0;
  cfl = gk_collisionless_flux_surfx_3x2v_ser_p1(
    w, dx, vmap, vmapSq, 1, 1, dgs, gkdgs, bmag, ratio, ratio, phi, f, f, flux);
  bad = 0;
  for (int i=0; i<24; ++i) bad += !isfinite(flux[i]);
  printf("r=1 control: nonfinite radial flux slots = %d/24, cfl = %.17g\n", bad, cfl);
  return 0;
}

