GKYL_CU_D static gk_collisionless_passive_flux_surf_t
choose_gk_collisionless_passive_flux_surf_conf_kern(int dir, int cdim, int vdim, int poly_order)
{
  if (dir == 0) {
    return ser_gk_collisionless_passive_flux_surfx_kernels[cv_index_passive[cdim].vdim[vdim]]
      .kernels[poly_order];
  } else if (dir == 1) {
    return ser_gk_collisionless_passive_flux_surfy_kernels[cv_index_passive[cdim].vdim[vdim]]
      .kernels[poly_order];
  } else if (dir == 2) {
    return ser_gk_collisionless_passive_flux_surfz_kernels[cv_index_passive[cdim].vdim[vdim]]
      .kernels[poly_order];
  }

  return NULL;
}

// Helper: choose lower-edge conf-surface kernel for a given direction.
GKYL_CU_D static gk_collisionless_passive_flux_surf_t
choose_gk_collisionless_passive_flux_edge_lo_surf_conf_kern(
  int dir, int cdim, int vdim, int poly_order, enum gkyl_gyrokinetic_bc_type bc
)
{
  if (bc == GKYL_BC_GK_SKIP) {
    if (dir == 0) {
      return ser_gk_collisionless_passive_flux_multib_boundary_surfx_kernels[cv_index_passive[cdim]
                                                                               .vdim[vdim]]
        .kernels[poly_order];
    } else if (dir == 1) {
      return ser_gk_collisionless_passive_flux_multib_boundary_surfy_kernels[cv_index_passive[cdim]
                                                                               .vdim[vdim]]
        .kernels[poly_order];
    } else if (dir == 2) {
      return ser_gk_collisionless_passive_flux_multib_boundary_surfz_kernels[cv_index_passive[cdim]
                                                                               .vdim[vdim]]
        .kernels[poly_order];
    } else {
      return NULL;
    }
  } else {
    if (dir == 0) {
      return ser_gk_collisionless_passive_flux_surfx_kernels[cv_index_passive[cdim].vdim[vdim]]
        .kernels[poly_order];
    } else if (dir == 1) {
      return ser_gk_collisionless_passive_flux_surfy_kernels[cv_index_passive[cdim].vdim[vdim]]
        .kernels[poly_order];
    } else if (dir == 2) {
      return ser_gk_collisionless_passive_flux_surfz_kernels[cv_index_passive[cdim].vdim[vdim]]
        .kernels[poly_order];
    } else {
      return NULL;
    }
  }

  return NULL;
}

// Helper: choose upper-edge conf-surface kernel for a given direction.
