  int dir, int cdim, int vdim, int poly_order, enum gkyl_gyrokinetic_bc_type bc
)
{
  if (bc == GKYL_BC_GK_SKIP) {
    if (dir == 0) {
      return ser_gk_collisionless_passive_flux_multib_boundary_edge_surfx_kernels
        [cv_index_passive[cdim].vdim[vdim]]
          .kernels[poly_order];
    } else if (dir == 1) {
      return ser_gk_collisionless_passive_flux_multib_boundary_edge_surfy_kernels
        [cv_index_passive[cdim].vdim[vdim]]
          .kernels[poly_order];
    } else if (dir == 2) {
      return ser_gk_collisionless_passive_flux_multib_boundary_edge_surfz_kernels
        [cv_index_passive[cdim].vdim[vdim]]
          .kernels[poly_order];
    } else {
      return NULL;
    }
  } else {
    if (dir == 0) {
      return ser_gk_collisionless_passive_flux_edge_surfx_kernels[cv_index_passive[cdim].vdim[vdim]]
        .kernels[poly_order];
    } else if (dir == 1) {
      return ser_gk_collisionless_passive_flux_edge_surfy_kernels[cv_index_passive[cdim].vdim[vdim]]
        .kernels[poly_order];
    } else if (dir == 2) {
      return ser_gk_collisionless_passive_flux_edge_surfz_kernels[cv_index_passive[cdim].vdim[vdim]]
        .kernels[poly_order];
    }
    return NULL;
  }

  return NULL;
}

