/* Shared layout and emitters for collisionless zero-flux boundary kernels. */
load("core/modal-basis.mac")$
load("core/nodal_operations/nodal_functions.mac")$
load(stringproc)$

/* A variant is [passive, cdim, vdim, direction, basis, polynomial order].
   Both edges and both ES/NO_BY use the same zero-flux kernel. */
gkZeroFluxVariants() := block([variants:[], passive, dims, dir],
  for passive in [false,true] do (
    for dims in [[1,1],[1,2],[2,2],[3,2]] do (
      for dir : 1 thru dims[1] do (
        variants : endcons([passive,dims[1],dims[2],dir,"ser",1], variants)
      )
    )
  ),
  variants
)$

gkZeroFluxName(variant) := block([prefix, dirLabels:["x","y","z"]],
  prefix : if variant[1] then "gk_collisionless_passive_flux_" else "gk_collisionless_flux_",
  sconcat(prefix,"zero_flux_surf",dirLabels[variant[4]],"_",variant[2],"x",variant[3],
    "v_",variant[5],"_p",variant[6])
)$

/* Keep source definitions and header declarations identical. */
writeGkZeroFluxSignature(fh, variant) := block([],
  printf(fh, "GKYL_CU_DH double ~a(~%", gkZeroFluxName(variant)),
  printf(fh, "  const double *w, const double *dxv,~%"),
  printf(fh, "  const double *vmap, const double *vmapSq, const double q_, const double m_,~%"),
  printf(fh, "  const struct gkyl_dg_surf_geom *dgs, const struct gkyl_gk_dg_surf_geom *gkdgs,~%"),
  printf(fh, "  const double *bmag, const double *jacobgeo_rat_surfL, const double *jacobgeo_rat_surfR,~%"),
  if variant[1] then
    printf(fh, "  const double *speedsL, const double *speedsR,~%")
  else
    printf(fh, "  const double *phi,~%"),
  printf(fh, "  const double *JfL, const double *JfR, double *GKYL_RESTRICT flux_surf)")
)$

buildGkZeroFluxKernel(fh, variant) := block(
  [varsC,bC,varsP,bP,vSub,surf_cvars,surf_vvars,surfNodes,numSurfNodes,offset,i],
  [varsC,bC,varsP,bP,vSub] : loadGkBasis(variant[5],variant[2],variant[3],variant[6]),
  surf_cvars : delete(varsP[variant[4]],varsC),
  surf_vvars : makelist(varsP[i],i,variant[2]+1,variant[2]+variant[3]),
  surfNodes : gaussOrdGkHyb(variant[6]+1,surf_cvars,surf_vvars),
  numSurfNodes : length(surfNodes),
  offset : (variant[4]-1)*numSurfNodes,
  printf(fh, "/* Generated by gyrokinetic/gk_collisionless/ms-gk_collisionless_flux-zero.mac. */~%"),
  printf(fh, "#include <gkyl_gk_collisionless_zero_flux_kernels.h>~%~%"),
  writeGkZeroFluxSignature(fh,variant),
  printf(fh, "~%{~%"),
  printf(fh, "  // Zero only this direction's flux block. No geometry or input evaluation.~%"),
  for i : offset thru offset+numSurfNodes-1 do
    printf(fh, "  flux_surf[~a] = 0.0;~%",i),
  printf(fh, "  return 0.0; // No boundary CFL contribution.~%}~%")
)$

generateGkZeroFluxSources(outDir) := block([variant,fh],
  for variant in gkZeroFluxVariants() do (
