static void
axial_bfield(double t, const double *xc, double *b, void *ctx)
{
  b[0] = b[1] = 0.0;
  b[2] = 2.0;
}

static bool
finite_bits(double x)
{
  uint64_t bits;
  memcpy(&bits, &x, sizeof(bits));
  return (bits & UINT64_C(0x7ff0000000000000)) != UINT64_C(0x7ff0000000000000);
}

static void
test_cylindrical_axis(void)
{
  struct gkyl_basis basis;
  gkyl_cart_modal_serendip(&basis, 3, 1);
  struct gkyl_rect_grid grid;
  double lower[3] = {0.0, -M_PI, -1.0};
  double upper[3] = {1.0, M_PI, 1.0};
  int cells[3] = {4, 8, 2};
  gkyl_rect_grid_init(&grid, 3, lower, upper, cells);
  struct gkyl_range range, ext_range;
  int nghost[3] = {1, 1, 1};
  gkyl_create_grid_ranges(&grid, nghost, &ext_range, &range);
  struct gkyl_position_map *pmap = gkyl_position_map_null_new();
  struct gkyl_gk_geometry_inp input = {
    .geometry_id = GKYL_GEOMETRY_CYLINDRICAL,
    .bfield_func = axial_bfield,
    .position_map = pmap,
    .grid = grid,
    .local = range,
    .local_ext = ext_range,
    .global = range,
    .global_ext = ext_range,
    .basis = basis,
    .geo_grid = grid,
    .geo_local = range,
    .geo_local_ext = ext_range,
    .geo_global = range,
    .geo_global_ext = ext_range,
    .geo_basis = basis,
  };

  struct gk_geometry *geo = gkyl_gk_geometry_cylindrical_inew(&input);
  struct gkyl_range_iter iter;
  gkyl_range_iter_init(&iter, &geo->nrange_int);
  while (gkyl_range_iter_next(&iter)) {
    long idx = gkyl_range_idx(&geo->nrange_int, iter.idx);
    const double *jacob = gkyl_array_cfetch(geo->geo_int.jacobgeo_nodal, idx);
    const double *cov = gkyl_array_cfetch(geo->geo_int.g_ij_nodal, idx);
    double r = jacob[0];
    TEST_CHECK(r > 0.0);
    TEST_CHECK(fabs(cov[3] - r * r) < 1e-14);
  }

  gkyl_range_iter_init(&iter, &range);
  while (gkyl_range_iter_next(&iter)) {
    long idx = gkyl_range_idx(&range, iter.idx);
    struct gkyl_array *fields[] = {geo->geo_int.jacobgeo_inv, geo->geo_int.jacobtot_inv,
                                   geo->geo_int.gxxj,         geo->geo_int.gxyj,
                                   geo->geo_int.gyyj,         geo->geo_int.gij};
    for (int i = 0; i < sizeof(fields) / sizeof(fields[0]); ++i) {
      const double *f = gkyl_array_cfetch(fields[i], idx);
      for (int k = 0; k < fields[i]->ncomp; ++k) {
        TEST_CHECK(finite_bits(f[k]));
      }
    }
  }

  int axis_node[3] = {
    geo->nrange_surf[0].lower[0], geo->nrange_surf[0].lower[1], geo->nrange_surf[0].lower[2]
  };
  long axis_idx = gkyl_range_idx(&geo->nrange_surf[0], axis_node);
  const double *axis_j = gkyl_array_cfetch(geo->geo_surf[0].jacobgeo_nodal, axis_idx);
  const double *axis_lenr = gkyl_array_cfetch(geo->geo_surf[0].lenr_nodal, axis_idx);
  const double *axis_jinv = gkyl_array_cfetch(geo->geo_surf[0].jacobtot_inv_nodal, axis_idx);
  TEST_CHECK(axis_j[0] == 0.0);
  TEST_CHECK(axis_lenr[0] == 0.0);
  TEST_CHECK(axis_jinv[0] == 0.0);

  gkyl_gk_geometry_release(geo);
  gkyl_position_map_release(pmap);
}

TEST_LIST = {{"cylindrical_axis", test_cylindrical_axis}, {NULL, NULL}};
