// Shared fixtures for the ES and passive collisionless flux updater tests.
#pragma once

#include <math.h>
#include <stdint.h>
#include <string.h>
#include <gkyl_array_ops.h>
#include <gkyl_gk_collisionless_flux.h>
#include <gkyl_gk_collisionless_passive_flux.h>
#include <gkyl_gk_geometry_cylindrical.h>
#include <gkyl_position_map.h>

static bool
finite_bits(double x)
{
  uint64_t bits;
  memcpy(&bits, &x, sizeof(bits));
  return (bits & UINT64_C(0x7ff0000000000000)) != UINT64_C(0x7ff0000000000000);
}

static void
axial_bfield(double t, const double *xc, double *b, void *ctx)
{
  b[0] = b[1] = 0.0;
  b[2] = 1.0;
}

static struct gkyl_array *
test_array(int ncomp, long size, bool use_gpu)
{
  return use_gpu ? gkyl_array_cu_dev_new(GKYL_DOUBLE, ncomp, size) :
                   gkyl_array_new(GKYL_DOUBLE, ncomp, size);
}

struct flux_result {
  struct gkyl_array *flux, *cfl;
  struct gkyl_range local, ext;
};

// mixed selects lower x, upper y and lower z zero-flux faces. All remaining
// boundaries and all interior faces must continue to compute their normal flux.
static struct flux_result
run_flux_updater(enum gkyl_gk_collisionless_type type, bool axis, bool mixed, bool use_gpu)
{
  struct gkyl_rect_grid grid, phase_grid, vel_grid;
  double lower[] = {axis ? 0.0 : 1.0, -M_PI, -1.0, -1.0, 0.0};
  double upper[] = {axis ? 1.0 : 2.0, M_PI, 1.0, 1.0, 1.0};
  int cells[] = {2, 4, 2, 2, 2}, ghosts[] = {1, 1, 1, 0, 0};
  gkyl_rect_grid_init(&grid, 3, lower, upper, cells);
  gkyl_rect_grid_init(&phase_grid, 5, lower, upper, cells);
  gkyl_rect_grid_init(&vel_grid, 2, lower+3, upper+3, cells+3);
  struct gkyl_range conf, conf_ext, phase, phase_ext, vel, vel_ext;
  gkyl_create_grid_ranges(&grid, ghosts, &conf_ext, &conf);
  gkyl_create_grid_ranges(&phase_grid, ghosts, &phase_ext, &phase);
  gkyl_create_grid_ranges(&vel_grid, ghosts+3, &vel_ext, &vel);
  struct gkyl_basis cbasis, pbasis;
  gkyl_cart_modal_serendip(&cbasis, 3, 1);
  gkyl_cart_modal_gkhybrid(&pbasis, 3, 2);
  struct gkyl_position_map *pmap = gkyl_position_map_null_new();
  struct gkyl_gk_geometry_inp geo_inp = {
    .geometry_id = GKYL_GEOMETRY_CYLINDRICAL, .bfield_func = axial_bfield,
    .position_map = pmap, .grid = grid, .local = conf, .local_ext = conf_ext,
    .global = conf, .global_ext = conf_ext, .basis = cbasis,
    .geo_grid = grid, .geo_local = conf, .geo_local_ext = conf_ext,
    .geo_global = conf, .geo_global_ext = conf_ext, .geo_basis = cbasis,
  };
  struct gk_geometry *geo = gkyl_gk_geometry_cylindrical_inew(&geo_inp);
  struct gkyl_dg_geom_inp dg_inp = {
    .grid = &grid, .range = &conf_ext, .nquad = 2, .skip_geometry_creation = true,
  };
  struct gkyl_gk_dg_geom_inp gkdg_inp = {
    .grid = &grid, .range = &conf_ext, .nquad = 2,
  };
  struct gkyl_dg_geom *dg = gkyl_dg_geom_new(&dg_inp);
  struct gkyl_gk_dg_geom *gkdg = gkyl_gk_dg_geom_new(&gkdg_inp);
  gkyl_gk_dg_geom_populate_vol(dg, gkdg, geo);
  gkyl_gk_dg_geom_populate_surf(dg, gkdg, geo);
  if (axis) {
    const struct gkyl_gk_dg_surf_geom *s = gkyl_gk_dg_geom_get_surf(gkdg, 0, conf.lower);
    TEST_CHECK(s[0].Jc == 0.0);
  }
  if (use_gpu) {
    struct gk_geometry *geo_dev = gkyl_gk_geometry_new(geo, &geo_inp, true);
    struct gkyl_dg_geom *dg_dev = gkyl_dg_geom_new_from_host(&dg_inp, dg, true);
    struct gkyl_gk_dg_geom *gkdg_dev = gkyl_gk_dg_geom_new_from_host(&gkdg_inp, gkdg, true);
    gkyl_gk_geometry_release(geo);
    gkyl_dg_geom_release(dg);
    gkyl_gk_dg_geom_release(gkdg);
    geo = geo_dev;
    dg = dg_dev;
    gkdg = gkdg_dev;
  }
  struct gkyl_velocity_map *vmap = gkyl_velocity_map_new(
    (struct gkyl_mapc2p_inp){0}, phase_grid, vel_grid, phase, phase_ext, vel, vel_ext, use_gpu);
  struct gkyl_array *phi_h = gkyl_array_new(GKYL_DOUBLE, 8, conf_ext.volume);
  struct gkyl_array *speeds_h = gkyl_array_new(GKYL_DOUBLE, 24, conf_ext.volume);
  struct gkyl_array *fin_h = gkyl_array_new(GKYL_DOUBLE, 48, phase_ext.volume);
  gkyl_array_clear(phi_h, 0.0);
  gkyl_array_clear(speeds_h, 0.0);
  gkyl_array_clear(fin_h, 0.0);
  for (long i = 0; i < conf_ext.volume; ++i) {
    double *p = gkyl_array_fetch(phi_h, i), *s = gkyl_array_fetch(speeds_h, i);
    // Synthetic modal fields with nonzero derivatives in each direction.
    p[0] = 1.0;
    p[1] = 0.1; p[2] = 0.2; p[3] = 0.3;
    s[0] = 1.0; s[8] = 2.0; s[16] = 3.0;
  }
  for (long i = 0; i < phase_ext.volume; ++i) {
    double *f = gkyl_array_fetch(fin_h, i);
    f[0] = 2.0;
  }
  struct gkyl_array *phi = test_array(8, conf_ext.volume, use_gpu);
  struct gkyl_array *speeds = test_array(24, conf_ext.volume, use_gpu);
  struct gkyl_array *fin = test_array(48, phase_ext.volume, use_gpu);
  struct gkyl_array *flux = test_array(88, phase_ext.volume, use_gpu);
  struct gkyl_array *cfl = test_array(1, phase_ext.volume, use_gpu);
  gkyl_array_copy(phi, phi_h);
  gkyl_array_copy(speeds, speeds_h);
  gkyl_array_copy(fin, fin_h);
  gkyl_array_clear(flux, -777.0);
  gkyl_array_clear(cfl, 0.0);
  enum gkyl_gyrokinetic_bc_type bc[6];
  for (int d = 0; d < 6; ++d) bc[d] = GKYL_BC_GK_SPECIES_ABSORB;
  if (mixed) bc[0] = bc[4] = bc[2] = GKYL_BC_GK_SPECIES_ZERO_FLUX;
  if (type == GKYL_GK_COLLISIONLESS_PASSIVE) {
    struct gkyl_gk_collisionless_passive_flux *up = gkyl_gk_collisionless_passive_flux_new(
      &phase_grid, &cbasis, &pbasis, speeds, 1.0, 1.0, geo, dg, gkdg, vmap, bc, use_gpu);
    gkyl_gk_collisionless_passive_flux_surf(up, &conf, &phase, &conf_ext, &phase_ext, fin, flux, cfl);
    gkyl_gk_collisionless_passive_flux_release(up);
  } else {
    struct gkyl_gk_collisionless_flux *up = gkyl_gk_collisionless_flux_new(
      &phase_grid, &cbasis, &pbasis, 1.0, 1.0, type, geo, dg, gkdg, vmap, bc, use_gpu);
    gkyl_gk_collisionless_flux_surf(up, &conf, &phase, &conf_ext, &phase_ext, phi, fin, flux, cfl);
    gkyl_gk_collisionless_flux_release(up);
  }
  struct flux_result result = {
    .flux = gkyl_array_new(GKYL_DOUBLE, 88, phase_ext.volume),
    .cfl = gkyl_array_new(GKYL_DOUBLE, 1, phase_ext.volume), .local = phase, .ext = phase_ext,
  };
  gkyl_array_copy(result.flux, flux);
  gkyl_array_copy(result.cfl, cfl);
  gkyl_array_release(phi_h); gkyl_array_release(speeds_h); gkyl_array_release(fin_h);
  gkyl_array_release(phi); gkyl_array_release(speeds); gkyl_array_release(fin);
  gkyl_array_release(flux); gkyl_array_release(cfl);
  gkyl_velocity_map_release(vmap);
  gkyl_gk_geometry_release(geo);
  gkyl_dg_geom_release(dg);
  gkyl_gk_dg_geom_release(gkdg);
  gkyl_position_map_release(pmap);
  return result;
}

static void
release_flux_result(struct flux_result r)
{
  gkyl_array_release(r.flux);
  gkyl_array_release(r.cfl);
}

static void
check_flux_updater(enum gkyl_gk_collisionless_type type, bool use_gpu)
{
  for (int axis = 0; axis < 2; ++axis) {
    struct flux_result mixed = run_flux_updater(type, axis, true, use_gpu);
    // The annulus allows a normal-flux reference at every face. At the axis,
    // use the CPU zero-flux result as the reference (also checks CUDA parity).
    struct flux_result ref = run_flux_updater(type, axis, axis, false);
    struct gkyl_range_iter iter;
    gkyl_range_iter_init(&iter, &mixed.ext);
    int nzero = 0, nnonzero = 0;
    while (gkyl_range_iter_next(&iter)) {
      long loc = gkyl_range_idx(&mixed.ext, iter.idx);
      const double *actual = gkyl_array_cfetch(mixed.flux, loc);
      const double *expected = gkyl_array_cfetch(ref.flux, loc);
      for (int k = 0; k < 88; ++k) {
        int dir = k/24;
        bool zero = false;
        if (dir < 3) {
          int face = dir == 1 ? mixed.local.upper[dir]+1 : mixed.local.lower[dir];
          zero = iter.idx[dir] == face;
          for (int d = 0; d < 5; ++d)
            if (d != dir && (iter.idx[d] < mixed.local.lower[d] || iter.idx[d] > mixed.local.upper[d])) zero = false;
        }
        TEST_CHECK(finite_bits(actual[k]));
        if (zero) {
          TEST_CHECK(actual[k] == 0.0);
          ++nzero;
        } else {
          TEST_CHECK(gkyl_compare(actual[k], expected[k], 1e-12));
          if (actual[k] != -777.0 && fabs(actual[k]) > 1e-12) ++nnonzero;
        }
      }
      const double *cfl = gkyl_array_cfetch(mixed.cfl, loc);
      TEST_CHECK(finite_bits(cfl[0]));
      TEST_CHECK(cfl[0] >= 0.0);
      if (axis) {
        const double *cfl_ref = gkyl_array_cfetch(ref.cfl, loc);
        TEST_CHECK(gkyl_compare(cfl[0], cfl_ref[0], 1e-12));
      }
    }
    TEST_CHECK(nzero > 0);
    TEST_CHECK(nnonzero > 0);
    release_flux_result(mixed);
    release_flux_result(ref);
  }
}

#include <acutest.h>
#include "gk_collisionless_flux_test.h"
#include <gkyl_gk_collisionless_flux_priv.h>

// Selectors are device functions in NVCC translation units. GPU dispatch is
// exercised through the public updater below; host selectors are tested here.
#ifndef __NVCC__
static void
test_zero_flux_kernels(void)
{
  int cdims[] = {1, 1, 2, 3}, vdims[] = {1, 2, 2, 2}, counts[] = {3, 6, 12, 24};
  for (int layout = 0; layout < 4; ++layout) {
    for (int dir = 0; dir < cdims[layout]; ++dir) {
      gk_collisionless_flux_surf_t kernels[] = {
        choose_gk_collisionless_flux_surf_conf_kern(dir, cdims[layout], vdims[layout], 1, GKYL_BC_GK_SPECIES_ZERO_FLUX),
        choose_gk_collisionless_flux_edge_surf_conf_kern(dir, cdims[layout], vdims[layout], 1, GKYL_BC_GK_SPECIES_ZERO_FLUX),
        choose_gk_collisionless_flux_no_by_surf_conf_kern(dir, cdims[layout], vdims[layout], 1, GKYL_BC_GK_SPECIES_ZERO_FLUX),
        choose_gk_collisionless_flux_no_by_edge_surf_conf_kern(dir, cdims[layout], vdims[layout], 1, GKYL_BC_GK_SPECIES_ZERO_FLUX),
      };
      for (int variant = 0; variant < 4; ++variant) {
        double flux[96];
        for (int k = 0; k < 96; ++k) flux[k] = k+1.0;
        TEST_ASSERT(kernels[variant] != NULL);
        // NULL inputs prove that even singular or absent geometry is never read.
        double cfl = kernels[variant](NULL, NULL, NULL, NULL, 0.0, 0.0, NULL, NULL,
          NULL, NULL, NULL, NULL, NULL, NULL, flux);
        TEST_CHECK(cfl == 0.0);
        for (int k = 0; k < 96; ++k) {
          bool zero = k >= dir*counts[layout] && k < (dir+1)*counts[layout];
          TEST_CHECK(flux[k] == (zero ? 0.0 : k+1.0));
        }
      }
    }
  }
}
#endif

static void test_es(void) { check_flux_updater(GKYL_GK_COLLISIONLESS_ES, false); }
static void test_no_by(void) { check_flux_updater(GKYL_GK_COLLISIONLESS_ES_NO_BY, false); }
#ifdef GKYL_HAVE_CUDA
static void test_es_cu(void) { check_flux_updater(GKYL_GK_COLLISIONLESS_ES, true); }
static void test_no_by_cu(void) { check_flux_updater(GKYL_GK_COLLISIONLESS_ES_NO_BY, true); }
#endif

TEST_LIST = {
#ifndef __NVCC__
  {"zero_flux_kernels", test_zero_flux_kernels},
#endif
  {"zero_flux_es", test_es}, {"zero_flux_no_by", test_no_by},
#ifdef GKYL_HAVE_CUDA
  {"zero_flux_es_cu", test_es_cu}, {"zero_flux_no_by_cu", test_no_by_cu},
#endif
  {NULL, NULL},
};

